INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('Camp Acorn at Somerset Hills YMCA', 'Greater Somerset County YMCA', 'https://www.gscymca.org/child-care-camps/somerset-hills-camp/', 'https://operations.daxko.com/Online/5029/ProgramsV2/Search.mvc?program_id=CMP47234&locations=B79&categories[0]=CAT1431', NULL, '908-766-7898', '140 Mt Airy Road', 'Basking Ridge', 'NJ', '07920', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','STEM','leadership']::text[], ARRAY['swim lessons','recreational swim','sports and games','arts','science and nature','weekly field trips','ga-ga','water play','clubs']::text[], NULL, 3, 17, NULL, 11, 'YMCA day camp at the Somerset Hills Y in Basking Ridge, 9 to 4, with swim lessons twice a week in the Y''s indoor pools, sports, arts, science and a weekly bus trip. Groups run from preschool (ages 3 to 5, 9 to 2) and KinderCamp through grades 1 to 6, plus teen travel camp for grades 7 to 9 and a CIT program for grades 10 to 11.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, FALSE, FALSE, TRUE, 'Full refund for cancellations before May 1, 2026; after that the Y keeps $50 per week per child, except for documented medical reasons. Fees are charged 14 days before each session.', NULL, NULL, NULL, NULL, 2026, '312ecdc9-42b6-5f45-a680-2e8253b87a00', 'camp-acorn-at-somerset-hills-ymca-basking-ridge', ST_GeogFromText('SRID=4326;POINT(-74.5523 40.7062)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.gscymca.org/child-care-camps/somerset-hills-camp/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Camp Clifton', 'Boys & Girls Club of Clifton', 'https://bgcclifton.org/summer-camp/', 'https://form.jotform.com/260575979813170', NULL, '973-773-2697', '181 Colfax Ave.', 'Clifton', 'NJ', '07013', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['swimming']::text[], ARRAY['swimming','field trips','color run','bowling','group activities']::text[], NULL, 6, 14, NULL, NULL, 'Full day Boys & Girls Club camp for members ages 6 to 14 (from 1st grade) at the Clifton clubhouse, 8:30 to 5:30 in one week sessions. Campers are grouped by age with a group leader, swim in the club pool, and can sign up for paid trips to water parks, amusement parks and bowling.', 'both', NULL, 160, 160, 160, 'week', NULL, NULL, TRUE, TRUE, 'A nonrefundable deposit equal to one month''s tuition is applied to the final month. Withdrawals must be filed 30 days before the final month; refunds come as portal credit, or less $10 by other means.', NULL, NULL, NULL, NULL, 2026, 'cfa62367-a6b4-51ed-a460-4d5e94cfdc52', 'camp-clifton-clifton', ST_GeogFromText('SRID=4326;POINT(-74.1604 40.8621)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://bgcclifton.org/deposit-refund-policy/','https://bgcclifton.org/summer-camp/','https://bgcclifton.org/wp-content/uploads/2026/05/Parent-Handbook-revised-2026.pdf']::text[], '2026-11-26', '2026-11-26', TRUE),
('Camp Riverbend', 'Camp Riverbend', 'https://www.campriverbend.com/', 'https://riverbend.campintouch.com/ui/forms/application/camper/App#ApplicationSeason', 'info@campriverbend.com', '908-580-2267', '116 Hillcrest Road', 'Warren', 'NJ', '07059', 'Northern New Jersey', 'day', ARRAY['general','outdoor']::text[], ARRAY['swimming','sports','arts','adventure','performing_arts']::text[], ARRAY['swimming','sports','high ropes','adventure course','ninja course','arts and crafts','nature','canoeing','kayaking','cooking','performing arts','circus arts','pedal karts','spray park','game pavilion']::text[], NULL, 3, 14, NULL, NULL, 'Family run day camp on about 30 acres along the Passaic River in Warren for ages 3 to 14. Campers swim twice a day in five heated pools and rotate through sports, high ropes, a ninja course, canoeing, cooking, arts, nature and circus arts; teens in grades 7 to 9 can join Day Trippers for trips around the region.', 'both', NULL, 2930, 9600, NULL, 'session', TRUE, TRUE, TRUE, NULL, '$500 deposit per camper, of which $200 becomes a non-refundable registration fee. Weeks are final on January 6, 2027; after that, tuition paid is not refundable. Missed days are not credited.', NULL, NULL, TRUE, 'https://www.campriverbend.com/rates-dates-application-2027', 2027, '9437415d-a7a2-51f1-9646-372ac1d3ee7d', 'camp-riverbend-warren', ST_GeogFromText('SRID=4326;POINT(-74.519 40.6346)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.campriverbend.com/','https://www.campriverbend.com/activities','https://www.campriverbend.com/lunch','https://www.campriverbend.com/rates-dates-application-2027']::text[], '2026-11-26', '2026-11-26', TRUE),
('Camp Sunrise Lake', 'Morris County Park Commission', 'https://www.morrisparks.net/2026-summer-camps/', 'https://njmorris.myvscloud.com/webtrac/web/search.html?Module=AR&type=DAYCP&category=rec', 'recreation@morrisparks.net', '973-326-7616', '270 Mendham Road', 'Morris Township', 'NJ', '07960', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts']::text[], ARRAY['lake swimming','inflatable obstacle course','water slides','sand castles','sports','games','arts and crafts']::text[], NULL, 5, 11, NULL, NULL, 'County park day camp at the Sunrise Lake Beach Club in Lewis Morris County Park for ages 5 to 11, 9 to 3:30. Half of each day is at the lake swimming, on the inflatable course and slides; the rest is sports, games and crafts.', 'outdoor', NULL, 340, 355, 355, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '4707a206-21db-576f-9f9f-0d97e8dd010a', 'camp-sunrise-lake-morris-township', ST_GeogFromText('SRID=4326;POINT(-74.4938 40.7961)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.morrisparks.net/2026-summer-camps/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Camp Timber at Bridgewater YMCA', 'Greater Somerset County YMCA', 'https://www.gscymca.org/child-care-camps/camp-timber/', NULL, NULL, '908-526-0688', '601 Garretson Road', 'Bridgewater', 'NJ', '08807', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','leadership']::text[], ARRAY['swimming lessons','archery','gaga','arts and humanities','sports and games','science and nature','theme days','weekly trips']::text[], NULL, 5, 16, 0, 10, 'Ten week YMCA day camp at the Bridgewater YMCA for children entering K to grade 10: Kindercamp, a traditional multi-activity camp for grades 1 to 7 with daily swim lessons and an archery range, and a counselor in training program for grades 8 to 10.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, 'Full refund for cancellations before May 1, 2026; after that the Y keeps $50 per week per child, except for documented medical reasons.', NULL, 'Daily swim lessons and free swim in the Y''s indoor pool.', TRUE, 'https://www.gscymca.org/child-care-camps/camp-timber/', 2026, '1feb0881-4b04-5026-a909-e65b3d24b703', 'camp-timber-bridgewater-ymca-bridgewater', ST_GeogFromText('SRID=4326;POINT(-74.604 40.5924)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.gscymca.org/child-care-camps/camp-timber/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Camp Vacamas Sleepaway Camp', 'Hands In 4 Youth', 'https://www.hi4y.org/sleepaway-camp', 'https://vacamas.campintouch.com/v2/camper/application/app0.aspx', 'registrar@hi4y.org', '973-838-0942', '256 Macopin Road', 'West Milford', 'NJ', '07480', 'Northern New Jersey', 'sleepaway', ARRAY['general']::text[], ARRAY['swimming','adventure','sports','outdoor']::text[], ARRAY['swimming','canoeing','boating','zip line','climbing walls','ropes course','basketball','volleyball','hiking','stage performances']::text[], NULL, 6, 17, NULL, NULL, 'Nonprofit overnight camp on a lake in West Milford with 12 and 19 day sessions for ages 6 to 17. Campers swim, canoe, climb, do a ropes course and zip line, and play sports, and fees follow a sliding scale based on family income.', 'both', NULL, 685, 2370, NULL, 'session', NULL, TRUE, TRUE, TRUE, NULL, NULL, 'Waterfront activities are run by American Red Cross certified swim instructors and lifeguards with a waterfront director.', TRUE, 'https://www.hi4y.org/sleepaway-camp', 2027, '48a85361-534c-5100-9696-ed1f112c97d6', 'camp-vacamas-sleepaway-camp-west-milford', ST_GeogFromText('SRID=4326;POINT(-74.391 41.1052)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.hi4y.org/sleepaway-camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('Day Camp Sunshine', 'Fellowship Deaconry Ministries', 'https://daycampsunshine.org/', 'http://cwngui.campwise.com/Customer/deaconry/browser-check-reg.html', 'camp@deaconry.org', '908-991-3215', '3575 Valley Road', 'Basking Ridge', 'NJ', '07920', 'Northern New Jersey', 'day', ARRAY['general','faith']::text[], ARRAY['swimming','adventure','arts']::text[], ARRAY['swimming','ropes course','zip line','climbing wall','giant swing','archery','arts and crafts','gaga','carpetball','four square','slip and slide','electives','bible lessons']::text[], NULL, 6, 15, 1, 9, 'Christian day camp in Basking Ridge, run by Fellowship Deaconry Ministries since 1938, for children entering grades 1 to 9 in grade based groups. Campers swim daily, do arts and crafts, gaga and weekly electives, with archery and a ropes course for older campers, plus daily Bible lessons.', 'outdoor', 'Christian', 345, 575, 575, 'week', TRUE, NULL, NULL, TRUE, '$35 registration fee and $50 a week deposit are not refundable. Cancellations before June 1 are refunded less those; after June 1 no refunds except medical emergency, though weeks can be swapped if space allows.', NULL, NULL, NULL, NULL, 2026, 'b407ebfe-532d-5f86-9632-1037c907b90f', 'day-camp-sunshine-basking-ridge', ST_GeogFromText('SRID=4326;POINT(-74.5523 40.7062)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://daycampsunshine.org/activities/','https://daycampsunshine.org/dates-rates/','https://daycampsunshine.org/policies-discounts/','https://daycampsunshine.org/programs/','https://daycampsunshine.org/programs/base-camp/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Summer Explorations', 'The Elisabeth Morrow School', 'https://elisabethmorrow.org/summer-explorations/', 'https://www.ultracamp.com/clientlogin.aspx?idCamp=523&campCode=ese', NULL, NULL, '435 Lydecker St.', 'Englewood', 'NJ', '07631', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['STEM','arts','technology','performing_arts','sports','leadership']::text[], ARRAY['science','art','technology','drama','sports','theme weeks','enrichment workshops','outdoor play']::text[], 'coed', 2, 15, NULL, 9, 'Summer program on the Elisabeth Morrow School''s 14 acre wooded campus in Englewood for age 2 through grade 9, half day (8:30 to 12:15) or full day (8:30 to 3:15). Young children have theme weeks in small classes, grades 2 to 6 pick weekly workshops in science, art, technology, drama and sports, and grades 7 to 9 have a three week Leaders in Training course.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, NULL, 'No refunds after May 1 for changes in plans; for health reasons the camp tries another session first, and gives a full refund with a medical provider''s note.', NULL, NULL, NULL, NULL, 2027, 'f57a2b47-dad9-5320-b132-431db33d3b7a', 'elisabeth-morrow-summer-explorations-englewood', ST_GeogFromText('SRID=4326;POINT(-73.9725 40.8912)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://elisabethmorrow.org/summer-explorations/','https://elisabethmorrow.org/summer-explorations/faq/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Essex County Environmental Center Nature Camp', 'Essex County Department of Parks, Recreation and Cultural Affairs', 'https://essexcountyparks.org/_media/_data/EssexResource/summer-camp-registration-packet-2026-tmc.pdf', 'https://essexcountyparks.org/calendar', 'dalexander@parks.essexcountynj.org', '973-228-8776', '621-B Eagle Rock Avenue', 'Roseland', 'NJ', '07068', 'Northern New Jersey', 'day', ARRAY['nature']::text[], ARRAY['outdoor','arts','leadership']::text[], ARRAY['hiking','canoeing','pond dipping','insect catching','bird watching','wilderness skills','nature art','citizen science','handicrafts','field trips','campfires']::text[], NULL, 4, 16, NULL, NULL, 'Weekly nature camps at the county''s Environmental Center in West Essex Park, each for a set age group from 4 to 16, with hiking, pond dipping, canoeing, wild art, wilderness skills and citizen science on the trails and Passaic River floodplain. Ages 4 and 5 go 9:30 to 12:30; older groups stay until 1:30.', 'both', NULL, 300, 400, 400, 'week', NULL, NULL, FALSE, TRUE, 'Cancel in writing at least 3 weeks before the week starts for a refund less a $50 administrative fee; no refund after that, though emergencies are considered case by case.', 'No staff trained for specialized medical, physical or behavioral needs and no one to one aides, but families may bring their own certified therapeutic support staff. Families are asked to call the program coordinator before registering.', NULL, NULL, NULL, 2026, '0d41300f-66a3-5bcc-a2bd-40d460717aae', 'essex-county-environmental-center-nature-camp-roseland', ST_GeogFromText('SRID=4326;POINT(-74.3101 40.8217)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://essexcountyparks.org/_media/_data/EssexResource/summer-camp-handbook-2026.pdf','https://essexcountyparks.org/_media/_data/EssexResource/summer-camp-registration-packet-2026-tmc.pdf']::text[], '2026-11-26', '2026-11-26', TRUE),
('Flat Rock Brook Summer Day Camp', 'Flat Rock Brook Nature Association', 'https://www.flatrockbrook.org/summer-camp-registration', 'https://www.flatrockbrook.org/summer-camp-registration', 'naturalist@flatrockbrook.org', '201-567-1265', '443 Van Nostrand Avenue', 'Englewood', 'NJ', '07631', 'Northern New Jersey', 'day', ARRAY['nature']::text[], ARRAY['outdoor','STEM']::text[], ARRAY['hiking','canoeing','pond and stream study','crafts','games','water games','gardening','birding']::text[], NULL, 4, 14, NULL, NULL, 'Weekly nature day camp on Flat Rock Brook''s 150 acre preserve in Englewood, 8:30 to 3, with daily hikes, pond and stream study, crafts and a canoe ride each week. Groups by age: Finch (4 to 5), Fox (6 to 7), Coyote Kids (8 to 10) and Junior Naturalists (11 to 14).', 'both', NULL, 450, 450, 450, 'week', TRUE, NULL, FALSE, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '66dfe835-db86-51d2-9493-2d1a96c064b4', 'flat-rock-brook-summer-day-camp-englewood', ST_GeogFromText('SRID=4326;POINT(-73.9725 40.8912)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.flatrockbrook.org/summer-camp-registration']::text[], '2026-11-26', '2026-11-26', TRUE),
('GSB Summer Camp', 'Gill St. Bernard''s School', 'https://www.gsbschool.org/summer/summer-camp', 'https://gsb.campmanagement.com/p/campers/login_m.php', NULL, '908-234-1611', 'St. Bernard''s Road', 'Peapack and Gladstone', 'NJ', '07934', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','leadership']::text[], ARRAY['swimming','sports','indoor and outdoor games','art projects','daily challenges']::text[], 'coed', 3, 15, NULL, NULL, 'Day camp on Gill St. Bernard''s 208 acre campus in Gladstone, 9 to 4, with swimming, sports, games, art and daily challenges. Day Camp serves grades K to 8, Kindercamp serves preschool and pre-K with half day options, and Leaders of Tomorrow trains grades 9 to 10 as junior counselors.', 'both', NULL, 925, 925, 925, 'week', TRUE, TRUE, NULL, NULL, NULL, NULL, NULL, TRUE, 'https://www.gsbschool.org/summer/summer-camp', 2026, '9e67a05d-454a-5d9f-a087-3e628fc65351', 'gsb-summer-camp-gladstone', ST_GeogFromText('SRID=4326;POINT(-74.6541 40.7158)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.gsbschool.org/summer/summer-camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('Harbor Hills Day Camp', 'Harbor Hills Day Camp', 'https://www.harborhillsdaycamp.com/', 'https://www.harborhillsdaycamp.com/enroll/', 'info@hhdc.com', '973-895-3200', '75 Doby Road', 'Mendham', 'NJ', '07945', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['sports','swimming','arts','adventure']::text[], ARRAY['sports','swimming','arts','adventure','boating','fishing','horseback riding','creative play','go karts','cooking','special events']::text[], NULL, NULL, 14, NULL, 8, 'Day camp in Mendham since 1963 for children entering pre K through 8th grade. Campers do sports, swimming, arts, adventure, boating, fishing and horseback riding, with choice periods from 2nd grade and electives for seniors; 7th and 8th graders can add a weekly day trip program.', 'outdoor', NULL, 5995, 9395, NULL, 'session', NULL, TRUE, TRUE, NULL, '$750 deposit at registration. All payments are fully refundable until February 1, 2027.', NULL, NULL, NULL, NULL, 2027, '0349ad44-5610-5e64-be0c-17449e104ec8', 'harbor-hills-day-camp-mendham', ST_GeogFromText('SRID=4326;POINT(-74.5978 40.7673)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.harborhillsdaycamp.com/','https://www.harborhillsdaycamp.com/2027-dates-and-rates/','https://www.harborhillsdaycamp.com/programs/']::text[], '2026-11-26', '2026-11-26', TRUE),
('iD Tech at Montclair State University', 'iD Tech', 'https://www.idtech.com/locations/new-jersey-summer-camps/montclair-state-university', 'https://www.idtech.com/register#/reg-flow/avail-charts-lock?lid=142&rgnad=true', 'hello@idtech.com', '1-888-709-8324', '1 Normal Ave', 'Montclair', 'NJ', '07043', 'Northern New Jersey', 'specialty', ARRAY['STEM','technology']::text[], NULL, ARRAY['coding','game development','robotics','3D printing','AI','Minecraft','Roblox','ultimate frisbee','capture the flag']::text[], NULL, 7, 17, NULL, NULL, 'Weeklong tech day camps on the Montclair State University campus for ages 7 to 17, with courses in coding, game development, robotics, AI and 3D printing taught in small groups in campus labs, plus outdoor games on the lawns between sessions.', 'both', NULL, 1079, NULL, NULL, 'week', FALSE, FALSE, FALSE, NULL, 'Full refund for cancellations before March 1. After March 1 and 28 or more days before the session, refund less fees and a $250 per week cancellation charge. No refunds within 28 days of the start.', NULL, NULL, NULL, NULL, 2027, '4ebb5269-da4b-5eb9-abef-bebef5f517e8', 'id-tech-at-montclair-state-university-montclair', ST_GeogFromText('SRID=4326;POINT(-74.209 40.8262)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.idtech.com/locations/new-jersey-summer-camps/montclair-state-university']::text[], '2026-11-26', '2026-11-26', TRUE),
('JCC Camp Ruach', NULL, 'https://jcccampruach.org/', 'https://ruach.campintouch.com/ui/forms/application/camper/App', 'asteinberg@ssbjcc.org', '908-443-9026', '775 Talamini Road', 'Bridgewater', 'NJ', '08807', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','adventure','performing_arts']::text[], ARRAY['swimming','swim lessons','athletics','art','ropes course','woodworking','electives','sports leagues','day trips','theater']::text[], NULL, 3, 15, NULL, 9, 'JCC day camp in Bridgewater, open to families of any background, for ages 3 through 9th grade. Campers swim twice a day and rotate through sports, art, a ropes course and electives; grades 4 to 9 take day trips twice a week to places like the beach and amusement parks.', 'both', 'Jewish', 2170, 8300, NULL, 'session', TRUE, TRUE, TRUE, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '386b9694-0f33-5607-b4e0-3fb2c23c8cd5', 'jcc-camp-ruach-bridgewater', ST_GeogFromText('SRID=4326;POINT(-74.604 40.5924)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://jcccampruach.org/','https://jcccampruach.org/age-groups/','https://jcccampruach.org/dates-and-rates/','https://jcccampruach.org/faq/']::text[], '2026-11-26', '2026-11-26', TRUE),
('JCC MetroWest Exploration Camp', 'JCC MetroWest', 'https://jccmetrowest.org/programs/camps/exploration-camp/', NULL, NULL, '973-530-3993', '760 Northfield Avenue', 'West Orange', 'NJ', '07052', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['STEM','arts','swimming']::text[], ARRAY['LEGO architecture','cooking','crafts','science','swimming','games','field trips']::text[], NULL, 5, 9, 0, 3, 'Weekly themed day camp at the JCC MetroWest building in West Orange for children entering K to grade 3, with three hours a day of teacher led instruction in topics like LEGO architecture, cooking, crafts and science, plus a daily free swim and games.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, NULL, NULL, 'Inclusive camp; families of campers who need extra support contact the JCC''s inclusion staff.', 'Daily free swim in the JCC''s indoor heated pools.', NULL, NULL, 2026, '9a1fb43a-c28e-5f0c-85dd-d87d0463114a', 'jcc-metrowest-exploration-camp-west-orange', ST_GeogFromText('SRID=4326;POINT(-74.2651 40.7858)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=760+Northfield+Avenue%2C+West+Orange%2C+NJ&benchmark=Public_AR_Current&format=json','https://jccmetrowest.org/programs/camps/','https://jccmetrowest.org/programs/camps/exploration-camp/']::text[], '2026-11-26', '2026-11-26', TRUE),
('LSC Science Camp', 'Liberty Science Center', 'https://lsc.org/camp', NULL, 'sciencecamp@lsc.org', '201-200-1000', '222 Jersey City Boulevard', 'Jersey City', 'NJ', '07305', 'Northern New Jersey', 'specialty', ARRAY['STEM']::text[], ARRAY['technology']::text[], ARRAY['hands-on STEM courses','game design','coding','robotics','engineering','museum exploration']::text[], NULL, 6, 14, 1, 8, 'Weekly STEM camp inside Liberty Science Center in Liberty State Park for grades 1 to 8, with a new themed course each week by grade band and daily time on the museum floors.', 'indoor', NULL, 1050, 1050, 1050, 'week', TRUE, FALSE, FALSE, NULL, 'The $150 deposit per session is non-refundable; other payments are refundable until May 1 and not after.', 'Welcomes campers with diverse needs but is not a specialized program; families contact the camp office to discuss accommodations. The museum is KultureCity sensory certified.', NULL, NULL, NULL, 2026, '59c1bda8-bbf3-53e2-9c87-45bd6849b011', 'liberty-science-center-science-camp-jersey-city', ST_GeogFromText('SRID=4326;POINT(-74.0648 40.7114)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://lsc.org/camp','https://lsc.org/camp/science-camp-faqs']::text[], '2026-11-26', '2026-11-26', TRUE),
('Mendham Day Camp', 'Mendham Borough Recreation', 'https://www.mendhamnj.org/cn/webpage.cfm?tpid=18987', 'https://www.mendhamnj.org/cn/webforms/form.cfm?FormID=10&tpid=17461', 'aegerter@mendhamnj.org', '973-543-8490', '44 Park Avenue', 'Mendham', 'NJ', '07945', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['sports','outdoor']::text[], ARRAY['water slide','kickball','relays','capture the flag','obstacle course','color wars','sports clinics','tie dye','magic show','boat building']::text[], NULL, 5, 12, 0, 6, 'Borough morning camp from 9 to 12:30 at Borough Park in Mendham for children in kindergarten through grade 6. Each week has a theme, such as water week with a water slide, sports week with visiting local teams, and a closing color wars week.', 'outdoor', NULL, 128, 188, 161, 'week', NULL, NULL, NULL, NULL, 'No refunds once registered. A camper who can''t attend because of a failed health screening may get credit for a later week.', NULL, NULL, NULL, NULL, 2026, '97315f8f-1edf-5208-8762-079afd12a3da', 'mendham-day-camp-mendham', ST_GeogFromText('SRID=4326;POINT(-74.5978 40.7673)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.mendhamnj.org/cn/webpage.cfm?tpid=18987','https://www.mendhamnj.org/cn/webpage.cfm?tpid=18992','https://www.mendhamnj.org/cn/webpage.cfm?tpid=19027','https://www.mendhamnj.org/cn/webpage.cfm?tpid=19034','https://www.mendhamnj.org/cn/webpage.cfm?tpid=19035','https://www.mendhamnj.org/documents/weekly_themes_flyer_2026.pdf']::text[], '2026-11-26', '2026-11-26', TRUE),
