('Montclair State University & Yogi Berra Museum Youth Camp', 'Montclair State University Baseball and Yogi Berra Museum & Learning Center', 'https://yogiberramuseum.org/learn/camps/', 'https://www.redhawkbaseballcamps.com/youth-camp.cfm', NULL, '973-655-3490', '8 Yogi Berra Dr.', 'Little Falls', 'NJ', '07424', 'Northern New Jersey', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['baseball','hitting','fielding','base running','pitching','game play','museum visit']::text[], NULL, 6, 13, NULL, NULL, 'Weeklong baseball camp for players of all abilities ages 6 to 13 at Yogi Berra Stadium on the Montclair State University campus, taught by MSU coaches and players. Campers work on hitting, defense, base running and pitching, play games, and spend part of one day in the Yogi Berra Museum next to the field.', 'both', NULL, 450.5, 450.5, 450.5, 'week', NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2027, 'c5999b67-5027-5076-921e-38a3fcda8b0a', 'montclair-state-university-yogi-berra-museum-youth-camp-little-falls', ST_GeogFromText('SRID=4326;POINT(-74.2174 40.8756)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.redhawkbaseballcamps.com/youth-camp.cfm','https://yogiberramuseum.org/learn/camps/']::text[], '2026-11-26', '2026-11-26', TRUE),
('New Horizons Day Camp', 'Dancesca, LLC', 'https://www.newhorizonsdaycamp.com/', 'https://newhorizons.campmanagement.com/p/request_for_info_m.php?action=enroll', 'info@NewHorizonsDayCamp.com', '973-850-6640', '235 Brooklake Road', 'Florham Park', 'NJ', '07932', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['sports','technology','arts','performing_arts','swimming','leadership']::text[], ARRAY['athletics','swimming','art','archery','media','coding','engineering','performing arts','cooking','podcasting','academic enrichment','counselor in training']::text[], NULL, NULL, 15, NULL, 9, 'Choice based day camp held at Brooklake Elementary School in Florham Park in 2027 for children entering pre K through 9th grade. From 2nd grade up campers build their own schedule from over 100 activities such as sports, swimming, art, archery, coding, engineering, media and performing arts; rising 9th graders can train as counselors.', 'both', NULL, 2500, 7275, NULL, 'session', TRUE, TRUE, TRUE, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, 'ccf61a66-616e-55f1-a176-d1958032dcc6', 'new-horizons-day-camp-florham-park', ST_GeogFromText('SRID=4326;POINT(-74.3943 40.776)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.newhorizonsdaycamp.com/','https://www.newhorizonsdaycamp.com/camp-hours-and-transportation','https://www.newhorizonsdaycamp.com/camp-lunch','https://www.newhorizonsdaycamp.com/our-program','https://www.newhorizonsdaycamp.com/rates-and-dates','https://www.newhorizonsdaycamp.com/scholarships-and-financial-aid']::text[], '2026-11-26', '2026-11-26', TRUE),
('Oak Crest Day Camp', 'Oak Crest Day Camp', 'https://summerdaycamp.oakcrestdaycamp.com/', 'https://oakcrest.campium.com/', 'info@oakcrestdaycamp.com', '732-297-2000', '92 Cortelyous Lane', 'Somerset', 'NJ', '08873', 'Northern New Jersey', 'day', ARRAY['general','outdoor']::text[], ARRAY['swimming','adventure','sports','performing_arts']::text[], ARRAY['swimming','bicycling','mountain biking','bmx','skatepark','rock climbing','climbing tower','zip line','giant swing','high ropes','archery','lacrosse','gaga','arts and crafts','drama','dance','day trips']::text[], NULL, 3, 15, NULL, NULL, 'Independently owned day camp in Somerset since 1961 for ages 3 to 15. Younger campers focus on swimming, biking, climbing and crafts; older ones add archery, high ropes, BMX and the skatepark, weekly choice activities, late nights and day trips, and teens in grades 7 to 9 travel on trips.', 'outdoor', NULL, 4100, 7600, NULL, 'session', TRUE, TRUE, TRUE, NULL, '$800 deposit per child. Full refund of what has been paid if you withdraw before April 1, 2027 (before January 15, 2027 for grades 7 to 9); weeks reduced before April 1 are refunded the difference.', NULL, NULL, NULL, NULL, 2027, '1df7abd5-b2e3-5705-ab68-ab896af07544', 'oak-crest-day-camp-somerset', ST_GeogFromText('SRID=4326;POINT(-74.5002 40.5085)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://summerdaycamp.oakcrestdaycamp.com/','https://www.oakcrestdaycamp.com/dates-rates/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Park Ridge Summer Camp', 'Park Ridge Recreation', 'https://www.parkridgeboro.com/resident/summer-camp-2026', 'https://register.communitypass.net/ParkRidgeBorough', NULL, NULL, NULL, 'Park Ridge', 'NJ', '07656', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['swimming']::text[], ARRAY['swimming','field games','bowling','movies']::text[], NULL, 5, 13, 0, 7, 'Borough morning camp for children entering kindergarten through grade 7. Mondays and Fridays are at the Park Ridge Municipal Pool, most other mornings at Memorial/Davies Field, with three Wednesdays at Montvale Lanes and one morning at a Westwood movie theater.', 'both', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '5ce2eb28-5642-5389-844e-45550b9c5962', 'park-ridge-summer-camp-park-ridge', ST_GeogFromText('SRID=4326;POINT(-74.0443 41.0362)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.parkridgeboro.com/committees/municipal-pool','https://www.parkridgeboro.com/resident/summer-camp-2026']::text[], '2026-11-26', '2026-11-26', TRUE),
('Pequannock Summer Camp', 'Boys & Girls Clubs of Northwest New Jersey', 'https://bgcnwnj.org/programs/camps-and-clinics/pequannock-summer-camp-.html', NULL, 'ddipsey@bgcnwnj.org', '973-633-9007', '19 Oak Avenue', 'Pequannock', 'NJ', '07440', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['sports','swimming','arts','STEM']::text[], ARRAY['swimming','arts and crafts','STEM','sports','game room','field trips','themed weeks']::text[], NULL, 5, 14, 0, 8, 'Full day Boys & Girls Club camp at the Pequannock clubhouse for kindergarten through grade 8, 7 AM to 6:30 PM. Kids swim three days a week at a local park, do STEM, art and sports, use the gym and game room, and go on weekly field trips; grades 6 to 8 have their own space.', 'both', NULL, 285, 320, 300, 'week', NULL, NULL, NULL, TRUE, 'Refunds until April 1. After that, refunds only if the spot can be filled, or in a family hardship.', NULL, NULL, NULL, NULL, 2026, 'c1808e3e-d1bc-5e5c-b2e4-af47d9d2b5a2', 'pequannock-summer-camp-pequannock', ST_GeogFromText('SRID=4326;POINT(-74.3052 40.9627)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://bgcnwnj.org/programs/camps-and-clinics/pequannock-summer-camp-.html']::text[], '2026-11-26', '2026-11-26', TRUE),
('Randolph Township Summer Day Camp', 'Randolph Township Parks, Recreation and Community Services', 'https://randolphnj.org/277/Summer-Camps-Sports-Clinics', 'https://register.capturepoint.com/reg/login.cfm?cuBMAf%2FClZwtomy3Erh3n%2B7fqxVPXoxk9V2eh8RZkO%2BWj9UZiY3p8g%3D%3D', NULL, '973-989-7081', NULL, 'Randolph', 'NJ', '07869', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['sports','arts','swimming']::text[], ARRAY['sports','games','arts and crafts','special events','guest visits','lake visits','carnival','talent show']::text[], NULL, 5, 11, 0, 5, 'Seven week township day camp at Freedom Park for children who finished kindergarten to grade 5, with sports, games, crafts, special events, guest visits and two trips a week to Randolph Lake.', 'outdoor', NULL, 250, 290, 250, 'week', TRUE, NULL, FALSE, NULL, 'Refunds must be requested in writing; requests by June 1 are refunded less a $25 fee per child per week, and nothing is refunded after June 1.', NULL, NULL, NULL, NULL, 2026, '98a889da-17e6-5a23-b716-400c6eb8df25', 'randolph-recreation-summer-day-camp-randolph', ST_GeogFromText('SRID=4326;POINT(-74.5785 40.8416)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://randolphnj.org/277/Summer-Camps-Sports-Clinics','https://randolphnj.org/DocumentCenter/View/354/Day-Camp-Brochure-PDF?bidId=']::text[], '2026-11-26', '2026-11-26', TRUE),
('Reeves-Reed Arboretum Summer Camps', 'Reeves-Reed Arboretum', 'https://www.reeves-reedarboretum.org/learn/camps/', NULL, 'a.llewellyn@reeves-reedarboretum.org', '908-273-8787', '165 Hobart Avenue', 'Summit', 'NJ', '07901', 'Northern New Jersey', 'day', ARRAY['nature']::text[], ARRAY['arts','performing_arts','STEM']::text[], ARRAY['garden exploration','hiking','nature crafts','games','stories','gardening','bird watching','cooking','dance','art']::text[], NULL, 4, 11, NULL, NULL, 'Weekly half day nature camps at a public garden in Summit for children from pre-K through rising grade 5, grouped by grade, with garden and trail walks, crafts, games and themes like animals, plants, birds and pollinators. Special weeks add a cooking camp and a full day dance and nature camp with BOLD Arts.', 'both', NULL, 300, 480, 300, 'week', NULL, NULL, FALSE, NULL, 'Cancel 30 days or more before camp starts for a refund less a $65 administrative fee; no refund within 30 days.', NULL, NULL, NULL, NULL, 2026, '6650e76a-436e-5d47-bd7f-7881c4603b91', 'reeves-reed-arboretum-summer-camps-summit', ST_GeogFromText('SRID=4326;POINT(-74.3651 40.7162)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.reeves-reedarboretum.org/content/uploads/2026/01/Brochure-for-website-2026-revised.pdf','https://www.reeves-reedarboretum.org/learn/camps/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Ridgewood YMCA Camp Woods', 'Ridgewood YMCA', 'https://www.ridgewoodymca.org/camp-woods/', 'https://www.ridgewoodymca.org/programs/29121/camp-woods-2027/?locations=13', NULL, '201-444-5600', '112 Oak Street', 'Ridgewood', 'NJ', '07450', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['sports','arts','swimming']::text[], ARRAY['swimming','sports','arts and crafts','games','field trips','theme days','special guests']::text[], NULL, 3, 14, NULL, NULL, 'YMCA day camp at the Ridgewood Y in downtown Ridgewood for ages 3 to 14, grouped 3 to 5, 6 to 7 and 8 to 14, with swimming, sports, crafts, weekly themes and field trips. Half days for ages 3 to 5.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '0d545647-0fc8-5acf-9a8d-722773535e94', 'ridgewood-ymca-camp-woods-ridgewood', ST_GeogFromText('SRID=4326;POINT(-74.1173 40.979)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.ridgewoodymca.org/camp-woods/','https://www.ridgewoodymca.org/day-camp/']::text[], '2026-11-26', '2026-11-26', TRUE),
('SpecialtyQuest Camp', 'Madison Area YMCA', 'https://madisonareaymca.org/camp/specialtyquest-camps', NULL, 'QuestCamps@madisonymca.org', '973-822-9622', '111 Kings Road', 'Madison', 'NJ', '07940', 'Northern New Jersey', 'day', ARRAY['arts','sports']::text[], ARRAY['performing_arts','swimming','STEM']::text[], ARRAY['fine arts','gymnastics','performing arts','sports','ninja gym','swim lessons','STEAM','theme days']::text[], NULL, 5, 11, 0, 5, 'Specialty day camp at the Madison Area YMCA Family Center for children entering kindergarten to grade 5, 8 to 5. Campers pick a focus (fine arts, gymnastics, performing arts, sports or ninja gym) and also get daily swim lessons, STEAM and Friday theme days.', 'both', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, 'b3c6f937-fdcc-50f1-a907-d1aaa6b1654b', 'specialtyquest-camp-madison', ST_GeogFromText('SRID=4326;POINT(-74.4162 40.759)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://madisonareaymca.org/camp/camp-payment-information','https://madisonareaymca.org/camp/specialtyquest-camps']::text[], '2026-11-26', '2026-11-26', TRUE),
('Spring Lake Day Camp', 'Spring Lake Day Camp', 'https://www.springlakedaycamp.com/', 'https://www.springlakedaycamp.com/register.html', 'friends@sldc.com', '973-831-9000', '234 Conklintown Road', 'Ringwood', 'NJ', '07456', 'Northern New Jersey', 'day', ARRAY['general','sports']::text[], ARRAY['swimming','arts','adventure','outdoor']::text[], ARRAY['swimming','boating','fishing','zip line','ropes course','climbing tower','baseball','softball','soccer','lacrosse','tennis','basketball','floor hockey','gaga','beach volleyball','dance','gymnastics','arts and crafts','ceramics','jewelry design','sewing','cooking','martial arts','science','nature','archery','music','drama']::text[], NULL, 3, 16, NULL, 10, 'Family run day camp on a 30 acre campus in Ringwood for nursery age children through 10th grade, with a five pool complex, a spring fed lake for boating and fishing, a zip line, ropes courses, field and court sports, arts, cooking and science. Full day runs 9:00 to 4:00; a half day Mini Day program serves 3 and 4 year olds.', 'both', NULL, 5995, 10595, NULL, 'session', NULL, TRUE, TRUE, NULL, NULL, NULL, NULL, TRUE, 'https://www.springlakedaycamp.com/about', 2027, 'f9ab608a-1fc8-5586-be50-93e2eeaa2498', 'spring-lake-day-camp-ringwood', ST_GeogFromText('SRID=4326;POINT(-74.2711 41.104)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.springlakedaycamp.com/','https://www.springlakedaycamp.com/about','https://www.springlakedaycamp.com/forms/SLDC-Dates-and-Rates-NJ.pdf']::text[], '2026-11-26', '2026-11-26', TRUE),
('Summer at Far Brook', 'Far Brook School', 'https://www.farbrook.org/summer-at-far-brook', 'https://summeratfarbrook.campbrainregistration.com/', 'summer@farbrook.org', '973-379-3442', '52 Great Hills Road', 'Short Hills', 'NJ', '07078', 'Northern New Jersey', 'day', ARRAY['general','arts']::text[], ARRAY['STEM','sports','performing_arts','outdoor']::text[], ARRAY['creative arts','science','music','theater','archery','outdoor play','water play','sports clinics','swim lessons']::text[], NULL, 3, NULL, NULL, NULL, 'Summer day camp on the Far Brook School campus in Short Hills, open to all families. Day campers rotate through art, science, music, theater, archery and outdoor play around a weekly theme, with water play on Fridays; the school also runs week long STEAM and specialty classes, sport clinics and leadership programs for older campers.', 'both', NULL, 495, 715, 695, 'week', TRUE, NULL, FALSE, NULL, '$50 registration fee is not refundable. Cancellations by May 31, 2026 are refunded less that fee; from June 1 families get a credit for unused weeks, good through summer 2027.', NULL, NULL, NULL, NULL, 2026, 'c3a3834f-6722-54ac-8314-a1f70434620b', 'summer-at-far-brook-short-hills', ST_GeogFromText('SRID=4326;POINT(-74.3262 40.7412)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.farbrook.org/summer-at-far-brook','https://www.farbrook.org/summer-at-far-brook/day-camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('Summer Arts Camp at The Growing Stage', 'The Growing Stage, The Children''s Theatre of New Jersey', 'https://growingstage.com/summer-arts-camp/', 'https://growingstage.ludus.com/index.php?show_id=200513781&bpo=24015', 'llawrence@growingstage.com', '973-347-4946', '7 Ledgewood Avenue', 'Netcong', 'NJ', '07857', 'Northern New Jersey', 'specialty', ARRAY['performing_arts']::text[], ARRAY['arts']::text[], ARRAY['drama','dance','music','stagecraft','art','theater games','performance']::text[], NULL, 5, 14, 0, 8, 'Week long theater camp at the historic Palace Theatre in Netcong, run by The Growing Stage children''s theatre. Campers from kindergarten through 8th grade take daily drama, dance, music and art classes in small groups and put on a themed show each Friday.', 'indoor', NULL, 350, 350, 350, 'week', NULL, NULL, FALSE, NULL, 'Full refund if cancelled before June 1; no refunds after June 1. Processing fees are not refundable.', NULL, NULL, NULL, NULL, 2026, '2f8be86a-7932-5d42-b9ce-8e5a37be6548', 'the-growing-stage-summer-arts-camp-netcong', ST_GeogFromText('SRID=4326;POINT(-74.7008 40.8992)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://growingstage.com/summer-arts-camp/','https://growingstage.com/summer-camp-health-safety-policies/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Peck Summer Program', 'The Peck School', 'https://www.peckschool.org/community/summer-program', 'https://www.peckschool.org/fs/pages/541', NULL, '973-539-8660', '247 South Street', 'Morristown', 'NJ', '07960', 'Northern New Jersey', 'day', ARRAY['academic','arts']::text[], ARRAY['STEM','sports','performing_arts']::text[], ARRAY['basketball','field hockey','lacrosse','multi sport','oceanography','engineering','chemistry','lego','laser cutting','visual arts','crafts','claymation','musical theater','music','ssat prep']::text[], NULL, 3, 14, NULL, 8, 'Two June weeks of half day enrichment classes on The Peck School campus in Morristown, open to children from the wider community. Children entering grades 1 to 8 pick morning and afternoon classes such as sports, ocean science, engineering, LEGO, art, claymation, music and musical theater for a 9:00 to 3:00 day; a morning program serves ages 3 to 5.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '47f48df5-9ee8-5d04-b50d-35d2bb1aa881', 'the-peck-school-summer-program-morristown', ST_GeogFromText('SRID=4326;POINT(-74.4812 40.7968)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.peckschool.org/community/summer-program']::text[], '2026-11-26', '2026-11-26', TRUE),
('Verona Recreation Summer Playgrounds', 'Verona Recreation Department', 'https://www.veronanj.org/departments/recreation/summercamp', 'https://register.communitypass.net/verona', NULL, '973-857-4830', NULL, 'Verona', 'NJ', '07044', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['sports','arts']::text[], ARRAY['arts and crafts','organized games','sports','free play','pool trips','field trips']::text[], NULL, 4, NULL, NULL, 8, 'Five week township playground camps for children turning 4 through grade 8, run at four Verona schools by age group: REC-LOT for pre-K and kindergarten, REC-PARK, Elementary Zone, and Junior and Summer Adventure, with crafts, games, sports and optional pool and field trips for older groups.', 'both', NULL, 400, 400, NULL, 'session', FALSE, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '45b0e31f-43e9-594d-9a65-c8f6e14c9537', 'verona-summer-playgrounds-verona', ST_GeogFromText('SRID=4326;POINT(-74.2429 40.8325)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.veronanj.org/departments/recreation/summercamp','https://www.veronanj.org/media/Recreation%20/Playgrounds/SUMMER%20PLAYGROUND%20GUIDE%202026A-%20ALL%20CAMPS.pdf']::text[], '2026-11-26', '2026-11-26', TRUE),
('Visual Arts Center of New Jersey Summer Art Camp for Kids', 'Visual Arts Center of New Jersey', 'https://www.artcenternj.org/school-studio/2026-summer-art-camp-for-kids-ages-5-9/', 'https://www.artcenternj.org/school-studio/register-now/', 'info@artcenternj.org', '908-273-9121', '68 Elm Street', 'Summit', 'NJ', '07901', 'Northern New Jersey', 'specialty', ARRAY['arts']::text[], NULL, ARRAY['painting','drawing','sculpture','ceramics','mixed media','printmaking','papier-mache']::text[], NULL, 5, 9, NULL, NULL, 'Weekly art camp for ages 5 to 9 at the Visual Arts Center in downtown Summit, 10 to 3 on weekdays. Small age groups make 2D and 3D projects around a weekly theme, such as comics and cartoons, animals or art from around the world, in paint, clay, pastel and mixed media.', 'indoor', NULL, 435, 530, 530, 'week', TRUE, NULL, FALSE, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '38af1288-b77d-5336-be7e-2c38f72f1bae', 'visual-arts-center-of-new-jersey-summer-art-camp-summit', ST_GeogFromText('SRID=4326;POINT(-74.3651 40.7162)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.artcenternj.org/school-studio/2026-summer-art-camp-for-kids-ages-5-9/','https://www.artcenternj.org/school-studio/art-camp/','https://www.artcenternj.org/school-studio/scholarships/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Wayne Rec Summer Camp', 'Wayne Township Parks and Recreation', 'https://waynetownship.com/wayne-rec-summer-camp/', NULL, NULL, '973-694-1800', '1 Pike Drive', 'Wayne', 'NJ', '07470', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['swimming','sports']::text[], ARRAY['swimming','outdoor games','sports','field trips','bounce house','obstacle course','wildlife shows','petting zoo','pony rides','carnival']::text[], NULL, 5, 12, 0, 6, 'Eight week township day camp at the Wayne Community Center for grades K to 6, with daily swimming in the indoor pool, outdoor games and sports, themed weeks and optional weekly field trips.', 'both', NULL, 250, 250, 250, 'week', TRUE, NULL, FALSE, NULL, NULL, NULL, 'Daily swimming in the Community Center''s indoor pool.', NULL, NULL, 2026, '5a2c9705-0780-5179-bf3e-d9a9eb0a8013', 'wayne-rec-summer-camp-wayne', ST_GeogFromText('SRID=4326;POINT(-74.2451 40.9459)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://waynetownship.com/wayne-rec-summer-camp/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Wayne Summer Day Camp', 'Boys & Girls Clubs of Northwest New Jersey', 'https://bgcnwnj.org/programs/camps-and-clinics/wayne-summer-camp.html', NULL, 'krebner@bgcnwnj.org', '973-956-0033', '153 Garside Avenue', 'Wayne', 'NJ', '07470', 'Northern New Jersey', 'day', ARRAY['general']::text[], ARRAY['sports','swimming','arts','technology']::text[], ARRAY['swimming','arts and crafts','gym games','computer lab','game room','field trips','science classes','cooking classes','carnival']::text[], NULL, 5, 14, 0, 8, 'Full day Boys & Girls Club camp at the air conditioned 36,000 square foot Wayne clubhouse for children entering kindergarten through grade 8, 7:15 AM to 6:30 PM. Kids play in two gyms, use the tech lab and game room, swim off site, and go on field trips that are included in tuition.', 'both', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Refunds until April 1, less a 5% processing fee. After that, refunds only if the spot can be filled, or in a family hardship.', NULL, NULL, NULL, NULL, 2026, 'fe1a495d-5184-50f1-a6e9-84e3d6cc5ff5', 'wayne-summer-day-camp-wayne', ST_GeogFromText('SRID=4326;POINT(-74.2451 40.9459)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://bgcnwnj.org/programs/camps-and-clinics/wayne-summer-camp.html']::text[], '2026-11-26', '2026-11-26', TRUE),
('Arrowhead Day Camp', 'Arrowhead Day Camp', 'https://arrowheaddaycamp.com/', 'https://arrowheaddaycamp.com/parent-resources/registration/', 'chiefarrowhead@comcast.net', '610-353-5437', '240 Dutton Mill Road', 'West Chester', 'PA', '19380', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','outdoor','arts']::text[], ARRAY['archery','arts and crafts','basketball','batting cages','big wheel track','computers','culinary arts','driving range','gaga','game room','gymnastics','horseback riding','lacrosse','boating','fishing','marksmanship','miniature golf','music','dance','drama','nature study','zip line','rock wall','soccer','softball','street hockey','swim instruction','tennis','volleyball']::text[], NULL, 4, 13, NULL, NULL, 'Traditional day camp in West Chester, running since 1956, for boys and girls ages 4 to 13. Tuition covers door to door busing, lunch and snacks, daily swim lessons in four heated pools and dozens of activities from archery and boating on the camp lake to gymnastics, zip line and tennis.', 'both', NULL, 4245, 6545, NULL, 'session', TRUE, TRUE, TRUE, NULL, 'A $500 deposit holds a spot; all but $100 of it is refundable until March 15, 2027. Full tuition is due April 30, 2027.', NULL, 'Each camper takes a swim test on day one and gets lessons in groups of 6 to 12 by ability across four heated pools, plus daily free swim; colored bands mark depth limits. The camp also has a man made fresh water lake for boating and fishing.', NULL, NULL, 2027, '4fe434ea-fc1a-592d-ba33-321aed8cd466', 'arrowhead-day-camp-west-chester', ST_GeogFromText('SRID=4326;POINT(-75.6054 39.9599)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://arrowheaddaycamp.com/','https://arrowheaddaycamp.com/parent-resources/dates-tuition/','https://arrowheaddaycamp.com/prospective-campers/faq/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Benchmark Camp', 'Benchmark School', 'https://www.benchmarkschool.org/summer-camp', NULL, NULL, '610-565-3741', '2107 North Providence Rd', 'Media', 'PA', '19063', 'Philadelphia, PA', 'specialty', ARRAY['academic']::text[], ARRAY['special_needs','swimming','adventure','arts','sports']::text[], ARRAY['reading and writing instruction','executive function skills','swimming','art','crafts','robotics','innovation lab','sports and games','ropes course','zipline']::text[], NULL, 6, 12, 1, 6, 'Five week summer program at Benchmark School in Media for rising 1st to 6th graders, built for bright kids with dyslexia, ADHD or other learning differences. Mornings mix small group reading, writing and executive function lessons with recreation; full day campers add afternoons of sports, swimming, art and a ropes course with a zipline.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, NULL, NULL, 'Designed for children with dyslexia, ADHD, auditory processing or other learning differences. Language arts classes have up to nine students with a head teacher and an assistant; new campers get a reading assessment after registering for class placement.', NULL, NULL, NULL, 2027, 'd80eb118-4561-590d-a401-9fdc995579af', 'benchmark-summer-camp-media', ST_GeogFromText('SRID=4326;POINT(-75.3883 39.92)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.benchmarkschool.org/summer-camp','https://www.benchmarkschool.org/summer-camp/pricing-and-reg','https://www.benchmarkschool.org/summer-camp/program-details','https://www.benchmarkschool.org/summer-camp/recreation-program']::text[], '2026-11-26', '2026-11-26', TRUE),
('Briar Bush Nature Center Summer Camp', 'Briar Bush Nature Center (Abington Township Parks and Recreation)', 'https://www.briarbush.org/summer-camp-guide', NULL, 'melissa@briarbush.org', '215-887-6603', '1212 Edge Hill Road', 'Abington', 'PA', '19001', 'Philadelphia, PA', 'day', ARRAY['nature']::text[], ARRAY['outdoor','arts','adventure']::text[], ARRAY['guided hikes','pond exploration','live animal encounters','bird observatory','nature crafts','field trips','kayaking','creek walking','farm tours','foraging','camping skills','night hikes']::text[], NULL, 4, 15, NULL, NULL, 'Weekly nature camps at Briar Bush''s 12.5 acre forest preserve in Abington, with themed half day camps for ages 4 to 6 and full day camps for ages 6 to 7 on site, van travel camps to regional parks and farms for ages 8 to 12, and one overnight camping week at Ricketts Glen State Park for ages 13 to 15.', 'both', NULL, 280, 655, 445, 'week', TRUE, NULL, FALSE, TRUE, 'Transfers or cancellations 15 or more days before the start date get an 80% refund (20% service fee); no transfers or refunds within 14 days of the start.', 'An inclusive program that tries to accommodate campers, but staff are not behavioral intervention professionals and may not manage every medical, behavioral or social need; families are asked to call about support. Campers must be toilet trained and able to communicate their needs.', NULL, NULL, NULL, 2027, '9ffb73ec-a814-5ed2-abc5-e6d1d980f54c', 'briar-bush-nature-center-summer-camp-abington', ST_GeogFromText('SRID=4326;POINT(-75.1142 40.1136)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.briarbush.org/summer-camp-guide']::text[], '2026-11-26', '2026-11-26', TRUE),
('Camp Galil', 'Habonim Dror Camp Galil', 'https://www.campgalil.org/', 'https://campgalil.campintouch.com/ui/forms/application/camper/App', 'info@campgalil.org', '215-832-0676', '146 Red Hill Road', 'Tinicum', 'PA', '18942', 'Philadelphia, PA', 'sleepaway', ARRAY['general']::text[], ARRAY['faith','outdoor','nature','performing_arts','sports','swimming','arts','leadership']::text[], ARRAY['nature','outdoor adventure','high ropes','performing arts','sports','swimming','arts and crafts','israel education','cultural judaism','overnight hikes','community service']::text[], NULL, 8, 16, NULL, NULL, 'Jewish overnight camp of the Habonim Dror youth movement on 63 acres in upper Bucks County, about 30 miles north of Philadelphia. Campers live in cabins by grade and do sports, arts, performing arts, nature and outdoor adventure, a heated pool with swim lessons for younger campers, Israel education and group decision making, with one to seven week sessions.', 'both', 'Jewish', 675, 12915, NULL, 'session', NULL, NULL, TRUE, TRUE, 'Deposit $750 ($375 for Taste of Galil), with $50 non-refundable. Withdraw in writing: full refund through February 28, then $200 in March, $500 in April, 20% in May, 50% June 1 to 10, and no refund after June 10.', NULL, NULL, NULL, NULL, 2027, '62626d9b-199c-5fee-b84f-d756aad69049', 'camp-galil-ottsville', ST_GeogFromText('SRID=4326;POINT(-75.0964 40.4858)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.campgalil.org/activities-at-camp/','https://www.campgalil.org/contact/','https://www.campgalil.org/dates-and-rates/','https://www.campgalil.org/faqs/','https://www.campgalil.org/location/','https://www.campgalil.org/payment-refund-policies/','https://www.campgalil.org/why-galil/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Camp Kweebec', 'Camp Kweebec', 'https://www.kweebec.com/', NULL, 'info@kweebec.com', '610-287-8117', '157 Game Farm Rd', 'Schwenksville', 'PA', '19473', 'Philadelphia, PA', 'sleepaway', ARRAY['general']::text[], ARRAY['sports','arts','performing_arts','swimming','adventure']::text[], ARRAY['lake swimming','pools','sports','tennis','horseback riding','zip lines','high ropes','low ropes','performing arts','visual arts','trips']::text[], 'coed', 6, 16, NULL, NULL, 'Traditional coed overnight camp for ages 6 to 16 on 200 acres in the Perkiomen Valley, about an hour northwest of Philadelphia. Campers live in age divisions, with boys and girls on separate sides of camp, and do sports, arts and performance, two lakes and two pools, tennis, horseback riding, zip lines and ropes courses.', 'both', NULL, 350, 13250, NULL, 'session', NULL, TRUE, TRUE, NULL, NULL, NULL, NULL, TRUE, 'https://www.kweebec.com/getting-to-know-us/', 2027, 'a960a560-31d5-5475-9f4e-aa72be27f9d0', 'camp-kweebec-schwenksville', ST_GeogFromText('SRID=4326;POINT(-75.4657 40.2579)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.kweebec.com/dates/','https://www.kweebec.com/getting-to-know-us/','https://www.kweebec.com/parent-faqs/','https://www.kweebec.com/why-7-weeks/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Camp Saginaw', 'Camp Saginaw', 'https://www.campsaginaw.com/', 'https://saginaw.campintouch.com/ui/forms/application/camper/App', NULL, '888-477-2267', '740 Saginaw Road', 'Oxford', 'PA', '19363', 'Philadelphia, PA', 'sleepaway', ARRAY['general']::text[], ARRAY['sports','arts','swimming','adventure']::text[], ARRAY['athletics','ceramics','arts','swimming','lake tubing','canoeing','wakeboarding','high ropes','low ropes','aerial course','zip lines','dirt bikes','archery','trips']::text[], 'coed', 6, 16, 1, 11, 'Family run coed overnight camp for about 400 kids ages 6 to 16 on over 400 wooded acres in southern Chester County, founded in 1927 and marking its 100th summer in 2027. Campers do athletics, arts and ceramics, two pools, a lake and Big Elk Creek, ropes and aerial courses, zip lines, dirt bikes and trips, in full, half and two week sessions.', 'both', NULL, 50, 13500, NULL, 'session', NULL, TRUE, TRUE, TRUE, 'A $2,500 deposit at enrollment, $500 of it a non-refundable application fee; no refunds for cancellations after January 1, 2027. A first time camper who leaves early gets the unused days refunded.', NULL, NULL, TRUE, 'https://www.campsaginaw.com/why-saginaw', 2027, '14d8b20e-08fe-5ef1-9f94-9b032817fbe2', 'camp-saginaw-oxford', ST_GeogFromText('SRID=4326;POINT(-77.0451 39.8495)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.campsaginaw.com/contact-us','https://www.campsaginaw.com/dates-rates','https://www.campsaginaw.com/why-saginaw','https://www.campsaginaw.com/why-saginaw/activities','https://www.campsaginaw.com/why-saginaw/health-nutrition']::text[], '2026-11-26', '2026-11-26', TRUE),
('Camp Schuylkill', 'The Schuylkill Center for Environmental Education', 'https://schuylkillcenter.org/education/camp-schuylkill/', NULL, NULL, '215-853-6249', '8480 Hagy''s Mill Road', 'Philadelphia', 'PA', '19128', 'Philadelphia, PA', 'day', ARRAY['nature']::text[], ARRAY['outdoor','arts']::text[], ARRAY['hiking','canoeing','stream and pond exploration','bird watching','plant identification','nature crafts','stewardship projects','field trips','overnight camping (ages 12 to 13)']::text[], NULL, 4, 13, NULL, NULL, 'Weekly nature day camp on the Schuylkill Center''s 365 acres in Roxborough for ages 4 to 13, grouped by age. Campers hike, canoe and explore the forest, streams and ponds around a weekly theme; ages 10 and up add stewardship projects and a weekly field trip, and ages 12 to 13 camp overnight on four Thursdays.', 'both', NULL, 500, 610, 500, 'week', TRUE, NULL, FALSE, TRUE, 'A 50% deposit holds a spot until April 19, 2027, and half of that deposit is refundable until then; after April 19 full payment is due and fees are non-refundable.', NULL, NULL, NULL, NULL, 2027, '77fae74a-42bd-5d25-aaa7-6de6345b218e', 'camp-schuylkill-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://schuylkillcenter.org/education/camp-schuylkill/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Camp TPS', 'The Philadelphia School', 'https://www.tpschool.org/tps-experience/camptps/summer-camp', NULL, 'camptps@tpschool.org', '215-545-5323', '2501 Lombard Street', 'Philadelphia', 'PA', '19146', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['arts','sports','STEM','nature']::text[], ARRAY['city outings','gardening','art','sports','swimming','water play','clay and cooking','coding','engineering','chess','theater','ultimate frisbee','printmaking','gymnastics']::text[], NULL, 4, NULL, NULL, NULL, 'Center City day camp at The Philadelphia School: City Country Day Camp (Seeds for preschool and K, Explorers for grades 1 to 5) explores Philadelphia, gardens and swims, alongside 30 plus weekly enrichment camps in sports, arts, cooking and tech up to grade 8.', 'both', NULL, 400, 500, 500, 'week', NULL, NULL, FALSE, TRUE, 'Deposits are non-refundable; changes or cancellations must be made before April 6.', NULL, NULL, NULL, NULL, 2026, '1fbb88c0-1074-5fcd-b512-551bdb7b7e2e', 'camp-tps-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.tpschool.org/fs/resource-manager/view/9a48e289-d803-4685-999e-f41ebc64bc22','https://www.tpschool.org/tps-experience/camptps/rates-and-info','https://www.tpschool.org/tps-experience/camptps/summer-camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('Camp Walnut', 'Walnut Street Theatre', 'https://www.walnutstreettheatre.org/education/camp.php', 'https://walnutstreettheatre.coursestorm.com/', NULL, '215-574-3550', '825 Walnut Street', 'Philadelphia', 'PA', '19107', 'Philadelphia, PA', 'specialty', ARRAY['performing_arts']::text[], ARRAY['arts']::text[], ARRAY['musical theatre','acting','improvisation','voice','dance','playwriting','on-camera skills','audition coaching','stage movement']::text[], NULL, 8, 18, NULL, NULL, 'Four week musical theatre camp at Walnut Street Theatre in Center City for ages 8 to 18, Monday to Thursday. Beginners in the Discovery Division write and stage an original musical with no audition; auditioned Development and Performance students rehearse a junior or youth edition musical, all ending in public performances at the theatre.', 'indoor', NULL, 1300, 1800, NULL, 'session', TRUE, NULL, NULL, TRUE, NULL, 'The theatre says it welcomes students of all abilities, including those with disabilities and children who are developmentally typical.', NULL, NULL, NULL, 2027, 'd0466c8a-843f-59d4-91f1-3a462a59f204', 'camp-walnut-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.cognitoforms.com/WalnutStreetTheatre1/WSTSchoolFinancialAidApplication','https://www.walnutstreettheatre.org/education/camp.php']::text[], '2026-11-26', '2026-11-26', TRUE),
('Cheltenham Center for the Arts Summer Art Camp', 'Cheltenham Center for the Arts', 'https://www.cheltenhamarts.org/summer-art-camp', 'https://campscui.active.com/orgs/CheltenhamCenterfortheArts?orglink=camps-registration', 'info@cheltenhamarts.org', '215-379-4660', '439 Ashbourne Road', 'Cheltenham', 'PA', '19012', 'Philadelphia, PA', 'specialty', ARRAY['arts']::text[], ARRAY['performing_arts','swimming']::text[], ARRAY['painting','drawing','printmaking','ceramics','sculpture','collage','theatre games','pool trips']::text[], NULL, 5, 12, NULL, NULL, 'Art day camp for ages 5 to 12 at Cheltenham Center for the Arts, mostly in two week themed sessions plus one week Crafty Kids weeks. Campers grouped by age rotate through painting, drawing, printmaking, clay, sculpture and theatre classes with professional art teachers, perform on the last day, and swim at a township pool on Wednesday afternoons.', 'indoor', NULL, 280, 650, NULL, 'session', NULL, NULL, FALSE, NULL, 'No refunds or proration for days missed because of a change in plans, vacation or illness.', NULL, NULL, NULL, NULL, 2026, 'cb106aaf-dc77-59a3-8583-20d220600c7a', 'cheltenham-center-for-the-arts-summer-art-camp-cheltenham', ST_GeogFromText('SRID=4326;POINT(-75.1382 40.0781)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.cheltenhamarts.org/art-camp/general-info-registration','https://www.cheltenhamarts.org/camp/summer-art-camp-programs-ages-5-12','https://www.cheltenhamarts.org/summer-art-camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('College Settlement Day Camp', 'College Settlement of Philadelphia', 'https://collegesettlement.org/day-camp', 'https://summercampsatcollegesettlement.campbrainregistration.com/', 'camps@collegesettlement.org', '215-542-7974', '590 Witmer Road', 'Horsham', 'PA', '19044', 'Philadelphia, PA', 'day', ARRAY['nature','general']::text[], ARRAY['outdoor','swimming','sports','arts']::text[], ARRAY['swimming','swim lessons','bike riding','creek crawls','fishing','forest exploration','hiking','farm and garden','boating','nutrition','music','crafts','group challenges','climbing tower','gaga','kickball','soccer','rugby','cooking','drama','hayrides']::text[], NULL, 7, 12, NULL, NULL, 'Two week day camp on a 235 acre property in Horsham for ages 7 to 12, mixing environmental activities like creek crawls, fishing, gardening and hiking with swimming, a bike riding program, a climbing tower and sports, with buses from Philadelphia.', 'outdoor', NULL, 920, 920, NULL, 'session', NULL, TRUE, TRUE, TRUE, 'Cancel any time before camp; the $75 deposit is refunded only with at least two weeks'' notice. No refund if a camper is dismissed for conduct; prorated refunds for medical departures.', NULL, NULL, NULL, NULL, 2026, 'a14cf81f-0286-5231-836b-aa1db176142b', 'college-settlement-day-camp-horsham', ST_GeogFromText('SRID=4326;POINT(-75.1665 40.1993)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://collegesettlement.org/contact-us','https://collegesettlement.org/day-camp','https://collegesettlement.org/directions','https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=590+Witmer+Road%2C+Horsham%2C+PA&benchmark=Public_AR_Current&format=json','https://img1.wsimg.com/blobby/go/cdb38923-bc76-4543-a37d-9694d134e5d1/2026%20Pricing%20%26%20Discounts-8ec0a57.pdf']::text[], '2026-11-26', '2026-11-26', TRUE),
('DEAN Camps at Haverford College', 'DEAN Camps', 'https://deanadventurecamps.com/haverford-summer-camp', NULL, 'deanteam@deancamps.com', '610-660-9600', '370 Lancaster Ave', 'Haverford', 'PA', '19041', 'Philadelphia, PA', 'day', ARRAY['arts']::text[], ARRAY['STEM','performing_arts','sports','swimming']::text[], ARRAY['woodworking','machine sewing','culinary arts','STEAM','performing arts','musical theater','design and style','fiber arts','writing and illustration','sports and games','swimming']::text[], NULL, 4, 16, NULL, NULL, 'Skills based day camp on Haverford College''s campus for ages 4 to 16. Campers pick weekly tracks such as woodworking, machine sewing, cooking, STEAM, performing arts, design, writing and illustration or sports, or sample them all in Trailblazers, with breakfast, lunch and an outdoor pool included in 10 hour days.', 'both', NULL, NULL, NULL, 799, 'week', TRUE, NULL, TRUE, FALSE, 'Before June 1, 2027, a refund less a $100 cancellation fee per camper and program; after June 1, no refunds, but families can switch programs if space allows or take a camp credit.', NULL, NULL, NULL, NULL, 2027, '9411ff86-5ee2-5bda-835f-5bf9570ebfe6', 'dean-adventure-camp-at-haverford-college-haverford', ST_GeogFromText('SRID=4326;POINT(-75.3101 40.0062)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://deanadventurecamps.com/faqs','https://deanadventurecamps.com/haverford-summer-camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('Dragon Gym Summer Camp (Berwyn)', 'Dragon Gym Martial Arts & Fitness', 'https://www.dragongym.com/practice_areas/martial-arts-summer-camp-in-chester-county-pa.cfm', 'https://linktr.ee/DGsummercamp', NULL, '610-647-4753', '800 Lancaster Ave, Lower Level', 'Berwyn', 'PA', '19312', 'Philadelphia, PA', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['martial arts']::text[], NULL, 4, 13, NULL, NULL, 'Week-long martial arts day camp at Dragon Gym''s Berwyn school, open to beginners and kids who don''t train there. Full day 8:00 to 4:00 for ages 6 to 13 and half day mornings or afternoons for ages 4 to 6.', 'indoor', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, NULL, 'Full refund for any week cancelled by April 1, 2027. Payment plans for campers attending two or more weeks.', NULL, NULL, NULL, NULL, 2027, 'c2017100-8358-5189-9f65-18b377015a67', 'dragon-gym-summer-camp-berwyn', ST_GeogFromText('SRID=4326;POINT(-75.4421 40.0388)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.dragongym.com/practice_areas/martial-arts-summer-camp-in-chester-county-pa.cfm']::text[], '2026-11-26', '2026-11-26', TRUE),
