('Dragon Gym Summer Camp (Malvern)', 'Dragon Gym Martial Arts & Fitness', 'https://www.dragongym.com/practice_areas/martial-arts-summer-camp-in-chester-county-pa.cfm', 'https://linktr.ee/DGsummercamp', NULL, '610-363-7575', '235 Lancaster Ave, Ste E-11 (Lincoln Ct Shopping Center)', 'Malvern', 'PA', '19355', 'Philadelphia, PA', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['martial arts']::text[], NULL, 4, 13, NULL, NULL, 'Week-long martial arts day camp at Dragon Gym''s Malvern school, open to beginners and kids who don''t train there. Full day 8:00 to 4:00 for ages 6 to 13 and half day mornings or afternoons for ages 4 to 6.', 'indoor', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, NULL, 'Full refund for any week cancelled by April 1, 2027. Payment plans for campers attending two or more weeks.', NULL, NULL, NULL, NULL, 2027, 'b9f571c0-e9e2-5ac5-9f33-2c1c7aee12e0', 'dragon-gym-summer-camp-malvern', ST_GeogFromText('SRID=4326;POINT(-75.5154 40.0331)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.dragongym.com/practice_areas/martial-arts-summer-camp-in-chester-county-pa.cfm']::text[], '2026-11-26', '2026-11-26', TRUE)
