('Easttown Township Summer Camp', 'Easttown Township Parks & Recreation', 'https://www.easttown.org/347/Summer-Camp', NULL, NULL, '610-687-3000', 'Hilltop Park, 570 Beaumont Road', 'Devon', 'PA', '19333', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['sports','arts','outdoor']::text[], ARRAY['arts and crafts','games','sports','pickleball','9-square','water wednesdays','themed thursdays']::text[], NULL, 6, 14, 1, 8, 'Half day township camp, 9:00 to noon on weekdays for five weeks in July, at Hilltop Park in Devon for rising 1st to rising 8th graders. Kids do crafts, games, competitive and cooperative sports, pickleball and 9-square, with Water Wednesdays and Themed Thursdays; you don''t need to live in Easttown to join.', 'outdoor', NULL, 75, 75, 75, 'week', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '139ee7a5-348b-5870-b052-96bbe18117e5', 'easttown-township-summer-camp-devon', ST_GeogFromText('SRID=4326;POINT(-75.4268 40.0489)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=570+Beaumont+Road%2C+Devon%2C+PA&benchmark=Public_AR_Current&format=json','https://www.easttown.org/347/Summer-Camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('ESF Summer Camps at Devon Preparatory School', 'ESF Camps', 'https://www.esfcamps.com/devon/', NULL, NULL, '610-688-3298', '363 N Valley Forge Rd', 'Devon', 'PA', '19333', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['sports','STEM','swimming','arts']::text[], ARRAY['swimming','swim lessons','sports','arts','science','engineering','technology','special events']::text[], NULL, NULL, 16, NULL, 10, 'ESF day camp on the Devon Preparatory School campus in Devon for boys and girls from rising preschool to grade 10. Campers are grouped by grade, swim with Red Cross certified lifeguards and instructors, and pick from more than 60 activities across sports, arts, science, engineering and technology.', 'both', NULL, 1530, 6615, NULL, 'session', TRUE, NULL, FALSE, NULL, 'Cancel by March 15, 2027 for a refund less the $50 registration fee (a full cancellation also costs $300 per child); from March 16 to June 1, 2027, a credit instead of a refund; no refunds or credits after June 1. An optional protection plan covers injury or illness.', NULL, NULL, NULL, NULL, 2027, 'b636ed9f-eb14-582c-900a-e99d5bc45f31', 'esf-summer-camps-at-devon-prep-devon', ST_GeogFromText('SRID=4326;POINT(-75.4268 40.0489)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.esfcamps.com/about/policy-information/','https://www.esfcamps.com/devon/','https://www.esfcamps.com/devon/rates/']::text[], '2026-11-26', '2026-11-26', TRUE),
('ESF Summer Camps at Friends Select School', 'ESF Camps', 'https://www.esfcamps.com/friendsselect/', NULL, NULL, '215-298-9145', '17th Street & Benjamin Franklin Parkway', 'Philadelphia', 'PA', '19103', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['sports','STEM','swimming','arts']::text[], ARRAY['swimming','swim lessons','sports','arts','science','engineering','technology','special events']::text[], NULL, NULL, 15, NULL, 9, 'ESF day camp on the Friends Select School campus in Center City Philadelphia for boys and girls from rising preschool to grade 9. Campers are grouped by grade, swim with Red Cross certified lifeguards and instructors, and pick from more than 60 activities across sports, arts, science, engineering and technology.', 'both', NULL, 1390, 6650, NULL, 'session', TRUE, NULL, FALSE, NULL, 'Cancel by March 15, 2027 for a refund less the $50 registration fee (a full cancellation also costs $300 per child); from March 16 to June 1, 2027, a credit instead of a refund; no refunds or credits after June 1. An optional protection plan covers injury or illness.', NULL, NULL, NULL, NULL, 2027, '0267f96a-2117-5f20-8432-08b8f1362d47', 'esf-summer-camps-at-friends-select-school-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.esfcamps.com/about/policy-information/','https://www.esfcamps.com/friendsselect/','https://www.esfcamps.com/friendsselect/rates-details/rates/']::text[], '2026-11-26', '2026-11-26', TRUE),
('ESF Summer Camps at Montgomery School', 'ESF Camps', 'https://www.esfcamps.com/montgomery/', NULL, NULL, '610-827-1800', '1141 Kimberton Road', 'West Pikeland', 'PA', '19425', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['sports','STEM','swimming','arts']::text[], ARRAY['swimming','swim lessons','sports','arts','science','engineering','technology','special events']::text[], NULL, NULL, 16, NULL, 10, 'ESF day camp on the Montgomery School campus in Chester Springs for boys and girls from rising preschool to grade 10. Campers are grouped by grade, swim with Red Cross certified lifeguards and instructors, and pick from more than 60 activities across sports, arts, science, engineering and technology.', 'both', NULL, 1290, 5535, NULL, 'session', TRUE, NULL, FALSE, NULL, 'Cancel by March 15, 2027 for a refund less the $50 registration fee (a full cancellation also costs $300 per child); from March 16 to June 1, 2027, a credit instead of a refund; no refunds or credits after June 1. An optional protection plan covers injury or illness.', NULL, NULL, NULL, NULL, 2027, '157484fa-3ecd-5eb8-b424-ab4c4e8806d9', 'esf-summer-camps-at-montgomery-school-chester-springs', ST_GeogFromText('SRID=4326;POINT(-75.6196 40.088)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.esfcamps.com/about/policy-information/','https://www.esfcamps.com/montgomery/','https://www.esfcamps.com/montgomery/rates/']::text[], '2026-11-26', '2026-11-26', TRUE),
('ESF Summer Camps at Norwood-Fontbonne Academy', 'ESF Camps', 'https://www.esfcamps.com/chestnuthill/', NULL, NULL, '215-247-7010', '8900 Norwood Avenue', 'Philadelphia', 'PA', '19118', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['sports','STEM','swimming','arts']::text[], ARRAY['swimming','swim lessons','sports','arts','science','engineering','technology','special events']::text[], NULL, NULL, 16, NULL, 10, 'ESF day camp on the Norwood-Fontbonne Academy campus in Chestnut Hill, Philadelphia for boys and girls from rising preschool to grade 10. Campers are grouped by grade, swim with Red Cross certified lifeguards and instructors, and pick from more than 60 activities across sports, arts, science, engineering and technology.', 'both', NULL, 1210, 5750, NULL, 'session', TRUE, NULL, FALSE, NULL, 'Cancel by March 15, 2027 for a refund less the $50 registration fee (a full cancellation also costs $300 per child); from March 16 to June 1, 2027, a credit instead of a refund; no refunds or credits after June 1. An optional protection plan covers injury or illness.', NULL, NULL, NULL, NULL, 2027, '76174041-c357-5e8c-80d7-1a0ee96f4512', 'esf-summer-camps-at-norwood-fontbonne-academy-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.esfcamps.com/about/policy-information/','https://www.esfcamps.com/chestnuthill/','https://www.esfcamps.com/chestnuthill/rates/']::text[], '2026-11-26', '2026-11-26', TRUE),
('ESF Summer Camps at The Haverford School', 'ESF Camps', 'https://www.esfcamps.com/haverford/', NULL, NULL, '610-642-0246', '450 Lancaster Avenue', 'Haverford', 'PA', '19041', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['sports','STEM','swimming','arts']::text[], ARRAY['swimming','swim lessons','sports','arts','science','engineering','technology','special events']::text[], NULL, NULL, 16, NULL, 10, 'ESF day camp on the The Haverford School campus in Haverford for boys and girls from rising preschool to grade 10. Campers are grouped by grade, swim with Red Cross certified lifeguards and instructors, and pick from more than 60 activities across sports, arts, science, engineering and technology.', 'both', NULL, 1580, 6080, NULL, 'session', TRUE, NULL, FALSE, NULL, 'Cancel by March 15, 2027 for a refund less the $50 registration fee (a full cancellation also costs $300 per child); from March 16 to June 1, 2027, a credit instead of a refund; no refunds or credits after June 1. An optional protection plan covers injury or illness.', NULL, NULL, NULL, NULL, 2027, 'a38aaee3-69aa-539b-932a-783ed71254dd', 'esf-summer-camps-at-the-haverford-school-haverford', ST_GeogFromText('SRID=4326;POINT(-75.3101 40.0062)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.esfcamps.com/about/policy-information/','https://www.esfcamps.com/haverford/','https://www.esfcamps.com/haverford/rates/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Tenderfoot Camp', 'Friends'' Central Summer Programs', 'https://www.fcsprograms.org/programs/tenderfoot-camp', 'https://friendscentral.campintouch.com/ui/forms/application/camper/App', 'SummerPrograms@friendscentral.org', '610-645-5132', '228 Old Gulph Road', 'Wynnewood', 'PA', '19096', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['swimming','arts','sports','nature']::text[], ARRAY['swimming','swim lessons','art','sports and games','music','maker','yoga','storybook','nature','dance','free play','themed weeks']::text[], NULL, 3, 6, NULL, NULL, 'Day camp for ages 3 to 6 on Friends'' Central''s Old Gulph Road Lower School campus in Wynnewood, with daily swim lessons and free swim in an outdoor pool, art, music, maker, nature, yoga and themed weeks in small age based bunks.', 'both', NULL, 2604, 5320, NULL, 'session', TRUE, NULL, NULL, FALSE, 'Cancel in writing by March 31, 2027 with a $250 fee per camper; no refunds from April 1, 2027, though canceled weeks can become an account credit.', NULL, 'Instructional swim every morning and required free swim in the afternoon in the outdoor pool, with at least five certified lifeguards on duty.', NULL, NULL, 2027, '3e5c673d-b6d3-5ddd-89d2-c8b3d0a41bc4', 'friends-central-tenderfoot-camp-wynnewood', ST_GeogFromText('SRID=4326;POINT(-75.2692 39.9976)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.fcsprograms.org/about-us/campus-overview','https://www.fcsprograms.org/about-us/faq','https://www.fcsprograms.org/contact-us','https://www.fcsprograms.org/enrollment/policies-and-procedures','https://www.fcsprograms.org/programs/tenderfoot-camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('GA Day Camp', 'Germantown Academy', 'https://www.gacamp.org/day-camp', 'https://campscui.active.com/orgs/GermantownAcademy?season=3738740', 'summer@gacamp.org', '267-405-7321', '340 Morris Road', 'Fort Washington', 'PA', '19034', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['swimming','adventure','sports','arts','STEM']::text[], ARRAY['swimming','ropes course','zip line','archery','athletics','arts and crafts','stem','science','music','nature','field trips']::text[], NULL, 4, 14, NULL, NULL, 'Weekly day camp on Germantown Academy''s 126 acre Fort Washington campus, grouped by grade from pre K to grade 8, with swimming in an indoor pool, ropes, zip line, archery, sports, arts and STEM; older campers add field trips.', 'both', NULL, 520, 625, 520, 'week', TRUE, FALSE, FALSE, NULL, 'Before May 1, cancel for a refund minus the $150 deposit. After May 1, refunds need the $60 a week Refund Protection bought before May 1 and return 75% of unused fees; full refunds only for documented medical reasons.', NULL, '25 yard indoor pool with certified lifeguards; grades 1 to 3 mix instructional and free swim daily, grades 4 to 5 have free swim.', NULL, NULL, 2026, 'e8570fc2-0325-5a46-8f0b-db4b61a005b2', 'ga-day-camp-fort-washington', ST_GeogFromText('SRID=4326;POINT(-75.1926 40.1408)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.gacamp.org/adventurers','https://www.gacamp.org/dates-rates','https://www.gacamp.org/day-camp','https://www.gacamp.org/day-camp-explorers','https://www.gacamp.org/for-parents','https://www.gacamp.org/pathfinders-and-trailblazers','https://www.gacamp.org/s/Refund-Policy-2026.pdf']::text[], '2026-11-26', '2026-11-26', TRUE),
('Hill Top Summer Camps', 'Hill Top Preparatory School', 'https://www.hilltopprep.org/summer-camp/', NULL, 'summeradventures@hilltopprep.org', '610-527-3230', '737 S Ithan Avenue', 'Bryn Mawr', 'PA', '19010', 'Philadelphia, PA', 'specialty', ARRAY['special_needs']::text[], ARRAY['general','technology','swimming']::text[], ARRAY['arts and crafts','STEM','cooking','outdoor sports','swimming','swim lessons','social skills','weekly trips','esports','game design','independent living skills']::text[], NULL, 7, 18, 2, 12, 'Summer programs for neurodiverse kids and teens at Hill Top Preparatory School. Summer Adventures (entering grades 2 to 9) rotates campers through art, STEM, cooking, sports and swimming with social skills practice and Friday trips; teens can choose an esports program or Pathways to Independence for life and work skills.', 'both', NULL, 945, 1150, 1000, 'week', TRUE, NULL, FALSE, NULL, NULL, 'Built for neurodiverse learners with a 5 to 1 camper to staff ratio. Campers need to communicate verbally and handle their own hygiene and bathroom needs. Non Hill Top families start with an inquiry, a tour and an interview to check fit. Many campers use Extended School Year funding through their district.', 'Summer Adventures swims Monday to Thursday: 30 minutes of lessons, then 30 minutes of free swim.', NULL, NULL, 2026, '9eb7192f-4a80-50d4-917a-1a5bab6c753d', 'hill-top-summer-camps-bryn-mawr', ST_GeogFromText('SRID=4326;POINT(-75.3162 40.0208)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.hilltopprep.org/summer-camp/','https://www.hilltopprep.org/summer-camp/summer-faq.cfm']::text[], '2026-11-26', '2026-11-26', TRUE),
('Holy Child Academy Summer Camp', 'Holy Child Academy', 'https://www.holychildacademy.com/student-life/summer-camp', NULL, 'camp@holychildacademy.com', '610-259-2712', '475 Shadeland Avenue', 'Drexel Hill', 'PA', '19026', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['arts','STEM','swimming']::text[], ARRAY['physical education','arts and crafts','culinary arts','STEM','world cultures','music','dance','swimming','water play','field trips']::text[], NULL, 2, 12, NULL, NULL, 'Day camp at Holy Child Academy in Drexel Hill with half and full days. Little Dragons (ages 2 to 3) stay in the early childhood rooms; traditional campers (rising pre-K to 6th grade) move through PE, crafts, cooking, STEM and world cultures, with water play on campus or bus trips to a swim club twice a week.', 'both', NULL, 190, 395, 395, 'week', TRUE, NULL, FALSE, NULL, 'Refunds are generally not given; the camp refunds a week only if it can fill the spot.', NULL, 'Little Dragons and rising pre-K to 1st grade have water play on campus twice a week (water slide, sprinkler, water tables). Rising 2nd graders and up ride a bus to Drexel Swim Club on Tuesday and Thursday afternoons, with lifeguards on duty.', NULL, NULL, 2027, 'bd8b187d-968b-5ea5-8231-f53922be420f', 'holy-child-academy-summer-camp-drexel-hill', ST_GeogFromText('SRID=4326;POINT(-75.3039 39.9495)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.holychildacademy.com/student-life/summer-camp','https://www.holychildacademy.com/student-life/summer-camp/summer-camp-faqs']::text[], '2026-11-26', '2026-11-26', TRUE),
('Jefferson STEM Summer Camp Experience', 'Thomas Jefferson University', 'https://www.jefferson.edu/academics/summer-academy/stem-summer-camp-experience.html', NULL, 'Fernando.Tovia@jefferson.edu', '215-951-5652', 'East Falls Campus, 4201 Henry Avenue', 'Philadelphia', 'PA', '19144', 'Philadelphia, PA', 'specialty', ARRAY['STEM']::text[], ARRAY['technology']::text[], ARRAY['engineering design','3d printing','data analytics','coding','supply chain planning','solidworks']::text[], NULL, 11, 15, 6, 9, 'Free three week engineering day camp on Jefferson''s East Falls campus for students entering grades 6 to 9, Monday to Thursday. Campers analyze Eagles and Phillies stats with data science, write code, design parts in SolidWorks and 3D print them, and plan a mock supply chain. Admission is by application with a teacher recommendation.', 'indoor', NULL, 0, 0, NULL, 'session', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'ce5e0ca6-2091-5902-b886-9e33c58e4eef', 'jefferson-stem-summer-camp-experience-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.jefferson.edu/about/locations.html','https://www.jefferson.edu/academics/summer-academy/stem-summer-camp-experience.html']::text[], '2026-11-26', '2026-11-26', TRUE),
('Lionville YMCA Camp (Camp Lionville)', 'YMCA of Greater Brandywine', 'https://ymcagbw.org/camps/lionville-ymca-camp', NULL, 'mhennessy@ymcagbw.org', '610-363-9622', '1 Shreiner Way', 'Exton', 'PA', '19341', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','adventure']::text[], ARRAY['swimming','gaga','pedal carts','arts and crafts','nature trails','sports','STEM','field trips']::text[], NULL, 4, 15, NULL, NULL, 'YMCA day camp run by the Lionville Community YMCA at two Exton sites in 2026: Church Farm School and the Lionville Community YMCA. Campers ages 5 to 12 swim daily, play gaga and sports, do crafts and take field trips every other week; there are half day art, STEM and preschool camps, and teens 12 to 15 in Teen Trek go on field trips Tuesday to Friday.', 'both', NULL, 217, 505, 449, 'week', TRUE, NULL, NULL, TRUE, 'Cancel at least two weeks before the camp week for a refund of fees paid, less the non-refundable $35 a week deposit; no refunds or changes within two weeks of the start, or for illness.', NULL, NULL, TRUE, 'https://ymcagbw.org/sites/default/files/2026-06/2026%20-%20LCY%20SC%20Grids.pdf', 2026, 'c064e533-d574-54e6-80a2-707c6ed6aa3b', 'lionville-ymca-camp-exton', ST_GeogFromText('SRID=4326;POINT(-75.6331 40.0299)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://ymcagbw.org/camps/lionville-ymca-camp','https://ymcagbw.org/sites/default/files/2025-12/2026CaregiverHandbook_Complete.pdf','https://ymcagbw.org/sites/default/files/2026-06/2026%20-%20LCY%20SC%20Grids.pdf']::text[], '2026-11-26', '2026-11-26', TRUE),
('Lower Merion Playground Activities Camp', 'Lower Merion Township Parks & Recreation', 'https://lowermerionpa.myrec.com/forms/6046_summer_2026__final.pdf', NULL, 'recreation@lowermerion.org', '610-645-6220', 'South Ardmore Park, 1420 Sussex Road', 'Wynnewood', 'PA', '19096', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['arts','outdoor']::text[], ARRAY['arts and crafts','games','group activities','special events','optional day trips']::text[], NULL, 6, NULL, NULL, NULL, 'Six week township playground camp, 9:00 to 3:00 on weekdays, for kids 6 and up who have finished kindergarten, run at four Lower Merion parks. Days are crafts, games, group activities and special events, with some optional paid day trips.', 'outdoor', NULL, 600, 600, NULL, 'summer', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'c01ec6b4-036f-50e6-8c78-1e0baf0b071a', 'lower-merion-playground-activities-camp-wynnewood', ST_GeogFromText('SRID=4326;POINT(-75.2692 39.9976)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://lowermerionpa.myrec.com/forms/6046_summer_2026__final.pdf','https://lowermerionpa.myrec.com/info/facilities/default.aspx']::text[], '2026-11-26', '2026-11-26', TRUE),
('Lower Merion Special Recreation Afternoon Camp', 'Lower Merion Township Parks & Recreation', 'https://lowermerionpa.myrec.com/forms/6046_summer_2026__final.pdf', NULL, 'recreation@lowermerion.org', '610-645-6220', 'Belmont Hills Pool, 122 Mary Watersford Rd', 'Bala Cynwyd', 'PA', '19004', 'Philadelphia, PA', 'day', ARRAY['special_needs']::text[], ARRAY['swimming']::text[], ARRAY['swimming']::text[], NULL, 7, 18, NULL, NULL, 'Afternoon camp for children and teens with special needs, ages 7 to 18, who spend the afternoon swimming with township staff at the Belmont Hills public pool. Runs Monday to Thursday, 1:30 to 4:30, for about six weeks with a group limit of six.', 'outdoor', NULL, 1020, 1020, NULL, 'summer', NULL, FALSE, NULL, NULL, 'No refund or makeup for weather cancellations; an extreme case such as a whole week lost is handled case by case with a credit toward a future program.', 'Program is for children with special needs; group limit of 6. Families in Lower Merion ESY may have after school transport from the school district.', 'Swimming at the Belmont Hills public pool with township staff, weather permitting.', NULL, NULL, 2026, 'f2dca7d9-43d6-5bc7-9c65-33fd9331d8bd', 'lower-merion-special-recreation-afternoon-camp-bala-cynwyd', ST_GeogFromText('SRID=4326;POINT(-75.2279 40.0116)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=122+Mary+Watersford+Rd%2C+Bala+Cynwyd%2C+PA&benchmark=Public_AR_Current&format=json','https://lowermerionpa.myrec.com/forms/6046_summer_2026__final.pdf']::text[], '2026-11-26', '2026-11-26', TRUE),
('Lower Merion Youth Firefighter Camp', 'Lower Merion Township Parks & Recreation', 'https://lowermerionpa.myrec.com/forms/6046_summer_2026__final.pdf', NULL, 'recreation@lowermerion.org', '610-645-6220', 'McMoran Park, 154 Mary Waters Ford Road', 'Bala Cynwyd', 'PA', '19004', 'Philadelphia, PA', 'specialty', ARRAY['leadership']::text[], ARRAY['STEM']::text[], ARRAY['fire safety','fire extinguisher training','hazmat','search and rescue']::text[], NULL, 8, 13, NULL, NULL, 'One week half day camp for ages 8 to 13 with the Lower Merion Fire Department at McMoran Park. Kids learn fire safety and prevention and a firefighter''s daily work through short lessons and hands on drills like extinguisher training, hazmat and search and rescue.', NULL, NULL, 180, 180, 180, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'd576a6fd-5e56-5dea-82cf-88794e766243', 'lower-merion-youth-firefighter-camp-bala-cynwyd', ST_GeogFromText('SRID=4326;POINT(-75.2279 40.0116)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://lowermerionpa.myrec.com/forms/6046_summer_2026__final.pdf','https://lowermerionpa.myrec.com/info/facilities/default.aspx']::text[], '2026-11-26', '2026-11-26', TRUE),
('Main Line Art Center Summer Art Camp', 'Main Line Art Center', 'https://mainlineart.org/classes/summer-art-camp/', NULL, 'info@mainlineart.org', '610-525-0272', '746 Panmure Road', 'Haverford', 'PA', '19041', 'Philadelphia, PA', 'specialty', ARRAY['arts']::text[], NULL, NULL, NULL, 5, 16, NULL, NULL, 'Weekly art camp in the Main Line Art Center studios in Haverford, themed A Summer of Color in 2026. Palette Pals (ages 5 to 9) rotate through art styles and media with several teaching artists, half or full day; pre-teens (10 to 12) and teens (13 to 16) take half day studios in a single medium and can pair two for a full day. Each week ends with an Art Party.', 'indoor', NULL, 284, 568, 568, 'week', TRUE, NULL, FALSE, TRUE, 'Withdrawals more than two weeks before a session get a full refund less a $50 fee per transaction; no refunds within two weeks. Switching sessions costs $25 and must be asked two weeks ahead.', 'The center offers reasonable accommodations; families should contact the camp director a month before their session.', NULL, NULL, NULL, 2026, '4a10ffd4-a30e-58e3-94f3-2d2957bd4d70', 'main-line-art-center-summer-art-camp-haverford', ST_GeogFromText('SRID=4326;POINT(-75.3101 40.0062)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://mainlineart.org/classes/summer-art-camp/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Miquon Day Camp', 'The Miquon School', 'https://www.miquon.org/camp/info-registration', 'https://miquondaycamp.campmanagement.com/p/request_for_info_m.php?action=enroll', 'campoffice@miquon.org', '610-828-1231', '2025 Harts Lane', 'Conshohocken', 'PA', '19428', 'Philadelphia, PA', 'day', ARRAY['general','nature']::text[], ARRAY['swimming','arts','performing_arts','sports']::text[], ARRAY['swimming','swim lessons','arts and crafts','athletics','drama','music','movement','nature','creek exploring','choice time']::text[], NULL, 5, 11, 0, 6, 'Traditional outdoor day camp on The Miquon School''s wooded campus in Whitemarsh Township for ages 5 to 11, with daily swimming including lessons, arts and crafts, athletics, drama, music, movement, nature and free choice time by the creek.', 'both', NULL, 525, 525, 525, 'week', TRUE, TRUE, NULL, NULL, 'Cancellations by email to the registrar. Early in the year Miquon keeps a 10% deposit and refunds the rest; from March 1 it keeps the deposit and half of other payments; from mid April there are no refunds, though week transfers may be possible for a fee.', NULL, '8 to 10 swim periods a week, four of them small group lessons, led by certified lifeguards.', TRUE, 'https://www.miquon.org/camp/info-registration', 2027, '59fe81fe-014e-5a4e-8d00-f290743b795d', 'miquon-day-camp-conshohocken', ST_GeogFromText('SRID=4326;POINT(-75.3041 40.0772)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.miquon.org/camp/a-campers-day-miquon','https://www.miquon.org/camp/a-campers-day-miquon/swimming','https://www.miquon.org/camp/after-camp-care','https://www.miquon.org/camp/camp-transportation','https://www.miquon.org/camp/contact-camp','https://www.miquon.org/camp/info-registration']::text[], '2026-11-26', '2026-11-26', TRUE),
('Oscar Lasko YMCA Camp (Camp OLY)', 'YMCA of Greater Brandywine', 'https://ymcagbw.org/camps/oscar-lasko-ymca-camp', NULL, 'cchristopher@ymcagbw.org', '610-696-9622', '1 E. Chestnut Street', 'West Chester', 'PA', '19380', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','STEM','technology']::text[], ARRAY['swimming','gaga','arts and crafts','basketball','gymnastics','ninja parkour','STEM','esports and gaming','field trips']::text[], NULL, 3, 15, NULL, NULL, 'YMCA day camp based at the Oscar Lasko YMCA in downtown West Chester for ages 3 to 15. Traditional campers travel to the Coatesville YMCA several times a week for nature, outdoor time and swimming and take field trips every other week; specialty, sports, gymnastics, ninja parkour, STEM, esports and BumbleBee adaptive camps stay at Oscar Lasko.', 'both', NULL, 225, 491, 385, 'week', TRUE, NULL, NULL, TRUE, 'Cancel at least two weeks before the camp week for a refund of fees paid, less the non-refundable $35 a week deposit; no refunds or changes within two weeks of the start, or for illness.', 'BumbleBee adaptive camp (ages 6 to 12, full or half day) serves campers with developmental and intellectual disabilities who need more support.', NULL, TRUE, 'https://ymcagbw.org/sites/default/files/2026-01/2026%20-%20OLY%20SC%20Grids.pdf', 2026, '18be1f58-4798-538b-bc85-4ea4db224a65', 'oscar-lasko-ymca-camp-west-chester', ST_GeogFromText('SRID=4326;POINT(-75.6054 39.9599)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://ymcagbw.org/camps/oscar-lasko-ymca-camp','https://ymcagbw.org/sites/default/files/2025-12/2026CaregiverHandbook_Complete.pdf','https://ymcagbw.org/sites/default/files/2026-01/2026%20-%20OLY%20SC%20Grids.pdf']::text[], '2026-11-26', '2026-11-26', TRUE),
('Settlement Music School Wynnefield Summer Jazz Camp', 'Settlement Music School', 'https://settlementmusic.org/music/kids-teens/summer-programs/', NULL, 'luke.honer@settlementmusic.org', NULL, '4910 Wynnefield Avenue', 'Philadelphia', 'PA', '19131', 'Philadelphia, PA', 'specialty', ARRAY['performing_arts']::text[], ARRAY['arts']::text[], ARRAY['jazz ensemble','improvisation','jazz harmony','final performance']::text[], NULL, 12, 18, NULL, NULL, 'One week jazz camp for ages 12 to 18 at Settlement Music School''s Wynnefield Branch, 9 to 3 daily, where students work on jazz harmony and improvisation with the school''s faculty, play in a group and give a final performance on the last day.', 'indoor', NULL, 590, 590, 590, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '30aa6c0e-6956-5d3d-9ef5-d990d3121a58', 'settlement-music-school-wynnefield-summer-jazz-camp-philadelphia', ST_GeogFromText('SRID=4326;POINT(-75.1652 39.9526)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=4910+Wynnefield+Avenue%2C+Philadelphia%2C+PA&benchmark=Public_AR_Current&format=json','https://settlementmusic.org/music/kids-teens/summer-programs/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Silver Lake Nature Center Summer Camp', 'Silver Lake Nature Center', 'https://silverlakenaturecenter.org/education/summer-camp/', NULL, 'v-hlhewchuk@buckscounty.org', '215-785-1177', '1306 Bath Road', 'Bristol', 'PA', '19007', 'Philadelphia, PA', 'day', ARRAY['nature']::text[], ARRAY['outdoor','arts','sports']::text[], ARRAY['hiking','nature exploration','games','outdoor sports','arts and crafts','experiments','tie dye','water games','kayaking','fishing']::text[], NULL, 5, 14, NULL, NULL, 'Weekly nature day camp at Silver Lake Nature Center in Bristol for ages 5 to 14, with hiking, games, crafts, experiments and water games, plus kayaking and fishing once a week. Lunch and snacks are included, and campers 9 to 14 can add one overnight at the center in July.', 'outdoor', NULL, 305, 305, 305, 'week', TRUE, NULL, TRUE, NULL, '50% refund when cancelled more than 7 days before camp; no refund within 7 days or for no-shows; full refund if the center cancels.', NULL, NULL, NULL, NULL, 2027, '1863ece0-8612-5036-9f22-665276977d73', 'silver-lake-nature-center-summer-camp-bristol', ST_GeogFromText('SRID=4326;POINT(-74.8523 40.1028)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://silverlakenaturecenter.org/education/summer-camp/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Summer at AIS', 'The Agnes Irwin School', 'https://www.agnesirwin.org/about/summeratais', 'https://agnesirwin.campbrainregistration.com/', 'summer@agnesirwin.org', '610-801-1284', '275 S. Ithan Ave', 'Rosemont', 'PA', '19010', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['arts','STEM','sports','nature']::text[], ARRAY['arts and crafts','STEAM','sports','games','dance','theater','music','painting','yoga','puzzle rooms','field trips','weekly themes']::text[], 'coed', 3, 13, NULL, 7, 'Day camp for boys and girls at The Agnes Irwin School in Rosemont. Little Explorers (age 3 to rising kindergarten) do themed crafts, outdoor time and water play; Explorers (rising grades 1 to 7) explore STEAM, the arts, athletics and field trips on a rotating schedule.', 'both', NULL, 300, 425, 425, 'week', NULL, NULL, NULL, NULL, 'Cancel in writing before April 30 for a full refund including the $100 deposit; before May 31 for a refund less the deposit; no refunds for weeks cancelled or missed after June 1. Week changes depend on space.', NULL, NULL, NULL, NULL, 2026, '67408be8-9f42-5d69-8a8b-32050f1277f3', 'summer-at-ais-rosemont', ST_GeogFromText('SRID=4326;POINT(-75.327 40.0306)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.agnesirwin.org/about/summeratais','https://www.agnesirwin.org/about/summeratais/explorers','https://www.agnesirwin.org/about/summeratais/little-explorers']::text[], '2026-11-26', '2026-11-26', TRUE),
('Summer Camp at AFS', 'Abington Friends School', 'https://www.abingtonfriends.net/our-community/summer-camp', NULL, 'rregalbuto@abingtonfriends.net', '215-886-4350', '575 Washington Lane', 'Jenkintown', 'PA', '19046', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','performing_arts']::text[], ARRAY['swimming','swim lessons','sports','tennis','archery','karate','drama','music','dance','art','games','storytelling','creative movement','outdoor adventures','science']::text[], NULL, 3, 12, NULL, NULL, 'Day camp on the Abington Friends School campus for ages 3 to 12, in four groups by age. Every camper swims daily in the school''s pools with lessons by ability, and older campers rotate through sports, archery, karate, drama, music, dance and art, then pick electives each afternoon.', 'both', NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '118f0147-7598-532f-ad27-183e15f286d0', 'summer-camp-at-afs-jenkintown', ST_GeogFromText('SRID=4326;POINT(-75.1298 40.0963)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.abingtonfriends.net/our-community/summer-camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('Summer Camp at Riverbend''s Gladwyne Preserve', 'Riverbend Environmental Education Center', 'https://www.riverbendeec.org/education-programs/nature-camps/summer-camp-at-riverbend-preserve', NULL, 'camps@riverbendeec.org', '610-527-5234', '1950 Spring Mill Road', 'Lower Merion', 'PA', '19035', 'Philadelphia, PA', 'day', ARRAY['nature']::text[], ARRAY['outdoor','leadership','adventure']::text[], ARRAY['hiking','stream exploration','camp animals','fort building','games','crafts','free play','weekly field trips (ages 11 to 13)']::text[], NULL, 5, 13, NULL, NULL, 'Riverbend''s original weekly nature day camp on its 30 acre Gladwyne preserve for ages 5 to 13, in four age groups. Campers hike, explore the stream and ponds, meet the camp animals and build forts; ages 9 to 10 add offsite Nature Quest days, and the 11 to 13 Trailblazers lead their own projects and take a field trip each week.', 'outdoor', NULL, 680, 680, 680, 'week', TRUE, NULL, NULL, TRUE, 'A $100 a week deposit is due at booking and is a non-refundable administration fee, as are transaction fees. Tuition balances are due in full and become non-refundable on June 1.', NULL, NULL, NULL, NULL, 2027, 'bb4f7004-881c-5599-9570-f47555e4085c', 'summer-camp-at-riverbends-gladwyne-preserve-gladwyne', ST_GeogFromText('SRID=4326;POINT(-75.279 40.0299)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.riverbendeec.org/education-programs/nature-camps/summer-camp-at-riverbend-preserve','https://www.riverbendeec.org/education-programs/nature-camps/summer-camp-hub','https://www.riverbendeec.org/education-programs/nature-camps/trailblazers-summer-camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('Summer Friends at MPFS', 'Media-Providence Friends School', 'https://www.mpfs.org/school-life/summer-friends-camp', 'https://summerfriends.campmanagement.com/p/index.php?subdomain=summerfriends', 'camp@mpfs.org', '610-565-1960', '125 West Third Street', 'Media', 'PA', '19063', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['swimming','arts','STEM']::text[], ARRAY['swimming','yoga','field trips','team building games','arts and crafts','STEAM playground','rain garden exploration','scavenger hunts','sports','talent show']::text[], NULL, 3, 10, NULL, NULL, 'Ten week day camp for ages 3 to 10 on the Media-Providence Friends School campus in downtown Media, with a new theme and often a field trip each week. Campers ages 5 and up swim twice a week at a nearby swim club, and every group starts Mondays with yoga.', NULL, NULL, NULL, NULL, 400, 'week', NULL, NULL, NULL, NULL, 'Registration is nonrefundable, with no reductions for days missed for illness, vacation or any other reason.', NULL, 'Campers 5 and up swim Wednesdays and Fridays at Knowlton Swim Club, with instructional and recreational swim led by certified water safety instructors.', NULL, NULL, 2026, '6f9e1925-bdfa-5b26-8806-78d23cfca4e3', 'summer-friends-at-mpfs-media', ST_GeogFromText('SRID=4326;POINT(-75.3883 39.92)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.mpfs.org/school-life/summer-friends-camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('Temple Ambler Middle School Summer Programs', 'Temple University Ambler', 'https://ambler.temple.edu/community/middle-school-summer-programs/2026-programming', NULL, 'summer@temple.edu', NULL, '580 Meetinghouse Road', 'Ambler', 'PA', '19002', 'Philadelphia, PA', 'specialty', ARRAY['STEM']::text[], ARRAY['nature','performing_arts','technology','outdoor']::text[], ARRAY['engineering','flight simulator','underwater robotics','film and tv acting','gardening','horticulture','botanical illustration','nature hikes','low ropes','ecology']::text[], NULL, 10, 15, 5, 9, 'One and two week day programs on Temple University''s Ambler campus for middle schoolers, 9:00 to 4:00. Each week has its own topic, such as STEM labs, a flight simulator, underwater robots tested in the campus pool, film and TV acting, gardening at the Ambler Arboretum, and an outdoor ecology camp with low ropes.', 'both', NULL, 325, 755, NULL, 'session', NULL, NULL, NULL, TRUE, 'Withdraw in writing at least three weeks before the start for a refund less a $50 fee. A 10% deposit holds a place, with the balance due two weeks before the first day.', NULL, NULL, NULL, NULL, 2026, '312cbb83-3a8d-595f-a897-98e5e13db984', 'temple-ambler-middle-school-summer-programs-ambler', ST_GeogFromText('SRID=4326;POINT(-75.2215 40.1564)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://ambler.temple.edu/community/middle-school-summer-programs','https://ambler.temple.edu/community/middle-school-summer-programs/2026-programming']::text[], '2026-11-26', '2026-11-26', TRUE),
('Tredyffrin Township Summer Day Camp', 'Tredyffrin Township Parks & Recreation', 'https://www.tredyffrin.org/Departments/Parks-Recreation/Camps-Recreation/Summer-Day-Camp', NULL, 'ccappello@tredyffrin.gov', '610-408-3604', 'Wilson Farm Park, 500 Lee Road', 'Chesterbrook', 'PA', '19087', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['arts','outdoor']::text[], ARRAY['crafts','scavenger hunts','talent shows','music','relay games','water activities','large group games']::text[], NULL, 3, 12, NULL, NULL, 'Half day township camp, 9:00 to noon, for ages 3 and a half to 12, held outdoors in the pavilions at Wilson Farm Park. Kids do crafts, scavenger hunts, music, relay and group games, water play and Fun Fridays; sign up for one week or all six.', 'outdoor', NULL, 100, 125, 125, 'week', NULL, NULL, NULL, NULL, 'No refunds once enrollment is processed, including days lost to rain.', NULL, NULL, NULL, NULL, 2026, 'fda981f7-c1af-5ad0-88e8-49186ec50777', 'tredyffrin-township-summer-day-camp-chesterbrook', ST_GeogFromText('SRID=4326;POINT(-75.4551 40.0704)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.tredyffrin.org/Departments/Parks-Recreation/Camps-Recreation/Summer-Day-Camp','https://www.tredyffrin.org/Parks/Wilson-Farm-Park']::text[], '2026-11-26', '2026-11-26', TRUE),
('Upper Main Line YMCA Camp (Camp UMLY)', 'YMCA of Greater Brandywine', 'https://ymcagbw.org/camps/upper-main-line-ymca-camp', NULL, 'bhoff@ymcagbw.org', '610-647-9622', '1416 Berwyn-Paoli Road', 'Berwyn', 'PA', '19312', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','nature','performing_arts']::text[], ARRAY['swimming','gaga','pedal carts','canoeing','arts and crafts','nature trails','sports','field trips','theater','dance','woodworking','farm','tennis','STEM and robotics']::text[], NULL, 5, 16, NULL, NULL, 'YMCA day camp at the Upper Main Line YMCA''s campus in Berwyn, beside Natural Lands'' Cassatt Preserve, for ages 5 to 16. Traditional campers swim daily, play sports and gaga, canoe, do crafts and take field trips every other week; specialty weeks cover theater, dance, nature, farm, woodworking, STEM, sports and tennis, plus BumbleBee adaptive camps.', 'both', NULL, 290, 655, 519, 'week', TRUE, NULL, NULL, TRUE, 'Cancel at least two weeks before the camp week for a refund of fees paid, less the non-refundable $35 a week deposit; no refunds or changes within two weeks of the start, or for illness.', 'BumbleBee adaptive camps (ages 6 to 12 and 12 to 16, full or half day) serve campers with developmental and intellectual disabilities who need more support.', NULL, TRUE, 'https://ymcagbw.org/sites/default/files/2026-03/2026%20-%20UMLY%20SC%20Grids.pdf', 2026, '025b4793-b419-51ed-a4ab-3175ef3cc3e1', 'upper-main-line-ymca-camp-berwyn', ST_GeogFromText('SRID=4326;POINT(-75.4421 40.0388)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://ymcagbw.org/camps/upper-main-line-ymca-camp','https://ymcagbw.org/sites/default/files/2025-12/2026CaregiverHandbook_Complete.pdf','https://ymcagbw.org/sites/default/files/2026-03/2026%20-%20UMLY%20SC%20Grids.pdf']::text[], '2026-11-26', '2026-11-26', TRUE),
('West Chester YMCA Camp', 'YMCA of Greater Brandywine', 'https://ymcagbw.org/camps/west-chester-ymca-camp', NULL, 'vgallagher@ymcagbw.org', '610-431-9622', '605 Airport Road', 'West Chester', 'PA', '19380', 'Philadelphia, PA', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','leadership']::text[], ARRAY['swimming','gaga','hammock village','arts and crafts','field games','sports','nature','field trips','swim stroke and conditioning']::text[], NULL, 5, 15, NULL, NULL, 'YMCA day camp at the West Chester Area YMCA for ages 5 to 15, grouped by age, with daily swimming, gaga, a hammock village, arts and crafts, sports and nature, and field trips every other week. Also offers aquatics camps for ages 7 to 11, Teen Trek for ages 12 to 15 and a Leaders in Training program.', 'both', NULL, 400, 505, 465, 'week', TRUE, NULL, NULL, TRUE, 'Cancel at least two weeks before the camp week for a refund of fees paid, less the non-refundable $35 a week deposit; no refunds or changes within two weeks of the start, or for illness.', NULL, NULL, TRUE, 'https://ymcagbw.org/sites/default/files/2026-02/2026%20-%20WCAY%20SC%20Grids.pdf', 2026, '31e099c6-0f9e-57d0-af19-af7ebfb97d52', 'west-chester-ymca-camp-west-chester', ST_GeogFromText('SRID=4326;POINT(-75.6054 39.9599)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://ymcagbw.org/camps/west-chester-ymca-camp','https://ymcagbw.org/sites/default/files/2025-12/2026CaregiverHandbook_Complete.pdf','https://ymcagbw.org/sites/default/files/2026-02/2026%20-%20WCAY%20SC%20Grids.pdf']::text[], '2026-11-26', '2026-11-26', TRUE),
('Boys & Girls Club of Mount Vernon Summer Program', 'Boys & Girls Club of Mount Vernon', 'https://www.bgcmvny.org/summer-programs/', NULL, 'info@bgcmvny.org', '914-668-9580', '350 South Sixth Avenue', 'Mount Vernon', 'NY', '10550', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['sports','STEM','arts','academic']::text[], ARRAY['STEM','arts','basketball clinics','swimming','dance','tennis','health and life skills','weekly field trips']::text[], NULL, 5, 13, NULL, NULL, 'Seven week summer program at the Boys & Girls Club of Mount Vernon for ages 5 to 13, with STEM and arts activities, life skills, sports including basketball clinics, weekly swimming, dance and tennis, and weekly field trips. Free breakfast and lunch are served.', NULL, NULL, 130, 130, 130, 'week', NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'de92feb6-2487-53a2-82ef-58725c206fcd', 'boys-and-girls-club-of-mount-vernon-summer-program-mount-vernon', ST_GeogFromText('SRID=4326;POINT(-73.8293 40.9131)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.bgcmvny.org/contact-us/','https://www.bgcmvny.org/summer-programs/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Camp PGT', 'The Play Group Theatre', 'https://www.playgroup.org/summer/', NULL, NULL, '914-946-4433', 'One North Broadway', 'White Plains', 'NY', '10601', 'Westchester County, NY', 'specialty', ARRAY['performing_arts']::text[], ARRAY['arts']::text[], ARRAY['acting','musical theatre','dance','voice','improv','on camera acting','playwriting','sketch comedy','stage combat','design and tech','crafts']::text[], NULL, 4, 18, NULL, NULL, 'A theatre day camp at The Play Group Theatre in White Plains for ages 4 to 18, with one and two week programs by age group. Younger campers take acting, dance, voice and improv and end each session with a show they help write; older students can add weeks of improv, playwriting, sketch comedy, on camera work or design and tech.', 'indoor', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '8de2e482-4260-5740-902f-d4989f995078', 'camp-pgt-white-plains', ST_GeogFromText('SRID=4326;POINT(-73.7629 41.034)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.playgroup.org/summer/','https://www.playgroup.org/summer/kids.php']::text[], '2026-11-26', '2026-11-26', TRUE),
('Challenge Camp', 'Challenge Camp', 'https://challengecamps.com/', 'https://app.campdoc.com/!/dn/login?r=challengecamp', 'info@challengecamps.com', '914-779-6024', 'Iona University, 715 North Avenue', 'New Rochelle', 'NY', '10801', 'Westchester County, NY', 'day', ARRAY['STEM','arts']::text[], ARRAY['academic','technology','sports','swimming']::text[], ARRAY['3D printing','art','chess','coding','cooking','drones','Dungeons & Dragons','esports','filmmaking','game design','Lego','magic','Minecraft','photography','podcasting','robotics','theatre','swimming','sports']::text[], NULL, 4, 15, NULL, NULL, 'An enrichment day camp at Iona University in New Rochelle for ages 4 to 15. Campers pick two morning workshops from more than 140 STEM and arts electives, such as coding, robotics, filmmaking and chess, then three afternoon periods of sports, swim or more enrichment; children entering kindergarten have their own program.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, TRUE, NULL, NULL, NULL, NULL, TRUE, 'https://challengecamps.com/', 2027, 'c62d98d9-b34d-5b88-ace9-190938c9cb06', 'challenge-camp-new-rochelle', ST_GeogFromText('SRID=4326;POINT(-73.7826 40.9115)'), TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://challengecamps.com/','https://challengecamps.com/faq/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Clay Art Center Summer Camp', 'Clay Art Center', 'https://www.clayartcenter.org/summer-clay-camp', NULL, 'camp@clayartcenter.org', '914-937-2047', '40 Beech Street', 'Port Chester', 'NY', '10573', 'Westchester County, NY', 'specialty', ARRAY['arts']::text[], '{}'::text[], ARRAY['handbuilding','sculpture','wheel throwing','glazing','gallery visits']::text[], NULL, 7, 15, NULL, NULL, 'Week long pottery camps at Clay Art Center in Port Chester for ages 7 to 15. Children 7 to 11 handbuild themed projects such as clay creatures, and 12 to 15 year olds learn to throw on the potter''s wheel; pieces are fired and glazed and families pick them up a few weeks later.', 'indoor', NULL, 392, 784, 784, 'week', TRUE, NULL, FALSE, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '78a02692-b13e-5390-9983-4c791bc4ad79', 'clay-art-center-summer-camp-port-chester', ST_GeogFromText('SRID=4326;POINT(-73.6672 41.0047)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.clayartcenter.org/summer-clay-camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('Cranberry Lake Nature Camp', 'Westchester County Parks', 'https://parks.westchestercountyny.gov/children-camps/nature-camps', 'https://sales.westchestergov.com/', NULL, '(914) 428-1005', '1609 Old Orchard Street', 'North Castle', 'NY', '10604', 'Westchester County, NY', 'day', ARRAY['nature']::text[], ARRAY['outdoor']::text[], ARRAY['hiking','wetland exploration','nature study','quarry history walks','campout']::text[], NULL, 6, 15, 1, 9, 'County run nature day camp at Cranberry Lake Preserve, a 200 acre preserve in North White Plains, for kids entering grades 1 to 9. Younger groups (grades 1 to 3 and 4 to 6) come by the week; grades 7 to 9 take two week sessions with an optional overnight campout.', NULL, NULL, 425, 750, 425, 'session', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '6f0b2c7f-cf33-5045-89da-b5a42e4e8880', 'cranberry-lake-nature-camp-north-white-plains', ST_GeogFromText('SRID=4326;POINT(-73.6905 41.1363)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://parks.westchestercountyny.gov/children-camps/nature-camps','https://parks.westchestercountyny.gov/cranberrylake']::text[], '2026-11-26', '2026-11-26', TRUE),
('Destination Science at Iona University', 'Destination Science', 'https://destinationscience.org/new-york-science-camps/', 'https://destinationscience.org/find-your-camp-results/?location=New+Rochelle%2C+NY+10801', 'info@destinationscience.org', '888-909-2822', 'Iona University Bronxville Campus, 171 White Plains Road', 'Bronxville', 'NY', '10708', 'Westchester County, NY', 'specialty', ARRAY['STEM']::text[], ARRAY['technology']::text[], ARRAY['science experiments','robotics','engineering challenges','filmmaking','outdoor games','camp rally']::text[], NULL, 5, 11, NULL, NULL, 'A week long science day camp for ages 5 to 11 on Iona University''s Bronxville campus. Each week has a theme, such as robotics, stop motion movie making or space engineering, and the day mixes hands on experiments with outdoor games and an end of day rally.', 'both', NULL, 469, 469, 469, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '1df5e234-444c-585a-b43c-fe4f7b5dcef0', 'destination-science-iona-bronxville', ST_GeogFromText('SRID=4326;POINT(-73.834 40.9376)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://destinationscience.org/find-your-camp-results/?location=New+Rochelle%2C+NY+10801','https://destinationscience.org/new-york-science-camps/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Elmwood Day Camp', 'Elmwood Day Camp', 'https://elmwooddaycamp.com/', 'https://elmwood.campintouch.com/ui/forms/application/camper/App', NULL, '914-592-6121', '900 Dobbs Ferry Road', 'White Plains', 'NY', '10607', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','performing_arts','adventure','STEM']::text[], ARRAY['swimming','athletics','creative arts','performing arts','natural play','adventure park','zip lines','climbing wall','archery','gymnastics','tennis','gaga','yoga','ceramics','woodworking','cooking','science and engineering','gardening','hiking and trips']::text[], 'coed', 3, 14, NULL, 8, 'A coed day camp on a wooded property in White Plains, about a mile from Ardsley, for children from age 3 through grade 8. Campers rotate through swim lessons in three heated pools, sports, arts, an adventure park with zip lines and a climbing wall, woodworking, cooking and science, with programs set by age.', 'both', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, 2027, 'bd6eafbc-be2b-5e01-8c65-550c4b599d5b', 'elmwood-day-camp-white-plains', ST_GeogFromText('SRID=4326;POINT(-73.7629 41.034)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://elmwooddaycamp.com/','https://elmwooddaycamp.com/about/our-place','https://elmwooddaycamp.com/about/transportation-westchester','https://elmwooddaycamp.com/elmwood-families/parent-handbook/lunch-snack-allergies','https://elmwooddaycamp.com/enrollment','https://elmwooddaycamp.com/program-activities']::text[], '2026-11-26', '2026-11-26', TRUE),
('Hackley Summer Programs', 'Hackley School', 'https://www.hackleysummer.org/', 'https://summerathackley.campbrainregistration.com/', 'summer@hackleyschool.org', '914-366-2675', '293 Benedict Avenue', 'Tarrytown', 'NY', '10591', 'Westchester County, NY', 'day', ARRAY['general','academic']::text[], ARRAY['arts','sports','STEM']::text[], ARRAY['academic enrichment','athletics','arts','STEM','specialty camps','sports camps']::text[], NULL, 5, 18, 0, 12, 'Two weeks of June programs on the Hackley School campus in Tarrytown for students entering kindergarten through grade 12, taught mostly by Hackley faculty. Families build a schedule from morning, afternoon and full day courses in academic enrichment, arts, STEM, games and sports camps.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, FALSE, TRUE, NULL, 'A $150 deposit per camper is non refundable. After registration, refunds are given only for a verifiable medical reason; a $50 fee applies to program changes from May 1 and none are made after June 1.', NULL, NULL, NULL, NULL, 2027, 'c2761d6d-a62e-5556-9ea5-29d9b2cd7583', 'hackley-summer-programs-tarrytown', ST_GeogFromText('SRID=4326;POINT(-73.8579 41.0762)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.hackleysummer.org/','https://www.hackleysummer.org/faqs']::text[], '2026-11-26', '2026-11-26', TRUE),
('Harvey Summer Camp', 'The Harvey School', 'https://www.harveyschool.org/harvey-summer-camp', 'https://harveycavaliercamp.campmanagement.com/p/request_for_info_m.php?action=enroll', NULL, '914-232-3161', '260 Jay Street', 'Katonah', 'NY', '10536', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['arts','sports','STEM','performing_arts','swimming']::text[], ARRAY['nature and hiking','science experiments','ceramics','robotics','drawing and painting','watercolor','special effects makeup','gaga','gardening','photography','Lego','tennis','tie dye','swimming','arts and crafts','graphic art','theater']::text[], NULL, 6, 15, 1, 9, 'A day camp on The Harvey School campus in Katonah for children entering grades 1 to 9, with a first grade program, the main day camp for grades 2 to 8, an art camp for grades 5 to 8 and a ninth grade camp with weekly trips. Campers choose classes such as ceramics, robotics, tennis, swim and photography.', 'both', NULL, 795, 995, 995, 'week', NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'ad29b404-12f1-5c27-b913-f14a5aacf6c0', 'harvey-summer-camp-katonah', ST_GeogFromText('SRID=4326;POINT(-73.6852 41.2551)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.harveyschool.org/harvey-summer-camp','https://www.harveyschool.org/harvey-summer-camp/day-camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('Hillside Day Camp', 'Village of Hastings-on-Hudson Parks & Recreation', 'https://www.hohny.gov/179/Hillside-Day-Camp-2026', NULL, 'HastingsDayCamp@hohny.gov', '914-478-2380', NULL, 'Hastings-on-Hudson', 'NY', '10706', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['arts','STEM','sports','swimming']::text[], ARRAY['science experiments','arts and crafts','music','sports','free swim','field trips']::text[], NULL, 6, 12, 1, 6, 'Village day camp at Hillside Elementary School for children entering 1st to 6th grade, 9 to 3, mixing science experiments, arts and crafts, music and sports, with free swim at Chemka Pool every day and several trips. Non-residents may join if space allows.', 'both', NULL, 350, 1100, 350, 'week', TRUE, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '49facbac-9018-54f3-9206-64098ff61761', 'hillside-day-camp-hastings-on-hudson', ST_GeogFromText('SRID=4326;POINT(-73.8812 40.988)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.hohny.gov/179/Hillside-Day-Camp-2026','https://www.hohny.gov/181/Before-After-Camp-Info','https://www.hohny.gov/182/Day-Camp-Info']::text[], '2026-11-26', '2026-11-26', TRUE),
('Hudson Country Montessori Summer Camp', 'Hudson Country Montessori School', 'https://www.hudsoncountry.org/new-rochelle-ny-campus/summer-camp', NULL, 'info@hudsoncountry.org', '914-636-6202', '340 Quaker Ridge Road', 'New Rochelle', 'NY', '10804', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['swimming','arts','sports','STEM']::text[], ARRAY['swimming instruction','sports','yoga','gymnastics','arts and crafts','music','gardening','cooking','STEAM','water play','field trips']::text[], NULL, 1, 12, NULL, NULL, 'A Montessori school''s summer camp in New Rochelle for toddlers from 18 months through age 12, grouped as toddlers, preschool (3 to 5), juniors (6 to 8) and seniors (9 to 12). Weeks follow a theme and include swim lessons in the on site pool, sports, cooking, music, gardening and STEAM, with field trips for the older groups.', 'both', NULL, 680, 830, 680, 'week', TRUE, NULL, NULL, NULL, 'A $220 deposit is due with the application; deposits and tuition are non refundable.', NULL, NULL, NULL, NULL, 2026, '5f089f53-45da-5024-a750-2d0407886128', 'hudson-country-montessori-summer-camp-new-rochelle', ST_GeogFromText('SRID=4326;POINT(-73.7826 40.9115)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.hudsoncountry.org/new-rochelle-ny-campus/summer-camp','https://www.hudsoncountry.org/uploads/files/2026-summer-tuition.pdf?v=1769722329819','https://www.hudsoncountry.org/uploads/files/summer-2026-brochure-around-the-world-2.pdf?v=1769618092487']::text[], '2026-11-26', '2026-11-26', TRUE),
('JBFC Summer Camps', 'Jacob Burns Film Center', 'https://burnsfilmcenter.org/education/jbfc-camp/', NULL, 'registrar@burnsfilmcenter.org', '914-773-7663', 'Media Arts Lab, 405 Manville Road', 'Pleasantville', 'NY', '10570', 'Westchester County, NY', 'specialty', ARRAY['arts','technology']::text[], '{}'::text[], ARRAY['filmmaking','stop motion animation','storyboarding','acting on camera','video editing','screenings']::text[], NULL, 9, 18, 4, 12, 'Two week filmmaking and stop motion animation camps at the Jacob Burns Film Center''s Media Arts Lab in Pleasantville, in small groups of up to 10 by grade from 4 to 12. Campers write, shoot and edit their own short films or animations and premiere them for families at the JBFC theater.', 'indoor', NULL, 2000, 2100, NULL, 'session', NULL, NULL, FALSE, TRUE, 'Full refund for withdrawal by March 31, 50% in April, none after April 30; full refund if JBFC cancels.', 'Families are asked to tell the JBFC about an IEP or any needed accommodations so staff can support the camper.', NULL, NULL, NULL, 2026, '14c9eda8-54fc-572a-9050-c82a5dea8437', 'jbfc-summer-camps-pleasantville', ST_GeogFromText('SRID=4326;POINT(-73.7841 41.134)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://burnsfilmcenter.org/about/visit/directions-parking/','https://burnsfilmcenter.org/camp-and-course-policies-at-the-lab/','https://burnsfilmcenter.org/education/jbfc-camp/','https://burnsfilmcenter.org/education/jbfc-camp/animation-camp-summer/','https://burnsfilmcenter.org/education/jbfc-camp/filmmaking-camp-summer/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Lenoir Nature Camp', 'Westchester County Parks', 'https://parks.westchestercountyny.gov/children-camps/nature-camps', 'https://sales.westchestergov.com/', NULL, '(914) 968-5851', '19 Dudley Street', 'Yonkers', 'NY', '10701', 'Westchester County, NY', 'day', ARRAY['nature']::text[], ARRAY['outdoor']::text[], ARRAY['arts and crafts','nature study','outdoor skills','cooperative games','stewardship projects']::text[], NULL, 6, 15, 1, 9, 'County run nature day camp at Lenoir Preserve in Yonkers for kids entering grades 1 to 9, with weekly themes such as insects, mammals, birds and plants. Days mix arts and crafts, nature study, outdoor skills and cooperative games; grades 7 to 9 have one Conservationists in Training week.', NULL, NULL, 425, 425, 425, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'd82c0c98-cab8-591d-a6b6-2c7ad075c739', 'lenoir-nature-camp-yonkers', ST_GeogFromText('SRID=4326;POINT(-73.8988 40.9312)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://parks.westchestercountyny.gov/children-camps/nature-camps','https://parks.westchestercountyny.gov/lenoirpreserve']::text[], '2026-11-26', '2026-11-26', TRUE),
('Marshlands Nature Camp', 'Westchester County Parks', 'https://parks.westchestercountyny.gov/children-camps/nature-camps', 'https://sales.westchestergov.com/', NULL, '(914) 835-4466', 'Route 1', 'Rye', 'NY', '10580', 'Westchester County, NY', 'day', ARRAY['nature']::text[], ARRAY['outdoor']::text[], ARRAY['salt marsh exploration','insect study','plant study','survival shelters','fire making','knife safety','cordage making','water purification']::text[], NULL, 6, 15, 1, 9, 'County run nature day camp at Marshlands Conservancy in Rye for kids entering grades 1 to 6, who take weekly expeditions into the salt marsh, fields and woods to study insects, plants and mammals. Grades 7 to 9 have a separate three day outdoor survival skills session in August.', NULL, NULL, 350, 425, 425, 'session', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'a4f43d98-331d-5a39-94b4-ddc8070b286d', 'marshlands-nature-camp-rye', ST_GeogFromText('SRID=4326;POINT(-73.6829 40.9809)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://parks.westchestercountyny.gov/children-camps/nature-camps','https://parks.westchestercountyny.gov/marshlandsconservancy']::text[], '2026-11-26', '2026-11-26', TRUE),
('Mohawk Day Camp', 'Mohawk Day Camp', 'https://campmohawk.com/', 'https://mohawk.campmanagement.com/apply/mdc', 'info@campmohawk.com', '914-949-2635', '200 Old Tarrytown Road', 'White Plains', 'NY', '10603', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','adventure']::text[], ARRAY['swimming','archery','climbing wall','high ropes','zip line','farm and animal care','gardening','sports','creative arts','performing arts']::text[], 'coed', 3, 14, NULL, NULL, 'Day camp in White Plains for ages 3 to 14 with twice daily swimming for younger campers, sports, arts, a ropes course, zip line, climbing wall and farm animals. Older campers choose part of their day, and grades 5 to 8 can add a one week overnight trip.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, 2027, 'a7dd0701-4292-53bd-b483-7daec2493d8e', 'mohawk-day-camp-white-plains', ST_GeogFromText('SRID=4326;POINT(-73.7629 41.034)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://campmohawk.com/','https://campmohawk.com/activities/','https://campmohawk.com/contact/','https://campmohawk.com/dates-sessions/','https://campmohawk.com/lets-eat/','https://campmohawk.com/transportation/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Mount Tom Day Camp', 'Mount Tom Day Camp', 'https://www.mounttomdaycamp.com/', 'https://mounttomdaycamp.campmanagement.com/enroll', 'info@mounttomdaycamp.com', '914-636-8130', '48 Mount Tom Road', 'New Rochelle', 'NY', '10805', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','adventure']::text[], ARRAY['swimming','athletics','performing and creative arts','outdoor adventure','nature','horseback riding','ninja warrior','circus arts','STEM','climbing wall']::text[], NULL, 3, 15, NULL, NULL, 'Day camp on the New Rochelle and Pelham Manor line for ages 3 to 15, with two swims a day including Red Cross lessons, sports, arts, a climbing wall and specialties such as horseback riding, circus arts and STEM. Each group is led by a professional educator, and families pick 2 to 8 weeks.', NULL, NULL, 2450, 9350, NULL, 'session', TRUE, TRUE, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '0695c5b2-6cff-5b89-a67f-32ddad72a1e9', 'mount-tom-day-camp-new-rochelle', ST_GeogFromText('SRID=4326;POINT(-73.7826 40.9115)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.mounttomdaycamp.com/activities/','https://www.mounttomdaycamp.com/dates-rates/','https://www.mounttomdaycamp.com/lunch/','https://www.mounttomdaycamp.com/transportation/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Muscoot Farm Young Farmers Camp', 'Westchester County Parks', 'https://parks.westchestercountyny.gov/children-camps/muscoot-young-farmers-camp', 'https://sales.westchestergov.com/webtrac/web/search.html?module=AR&TYPE=YF&search=Yes', NULL, '(914) 864-7286', 'Route 100', 'Somers', 'NY', '10536', 'Westchester County, NY', 'day', ARRAY['nature']::text[], ARRAY['outdoor']::text[], ARRAY['animal care','farm chores','ponding','hiking','cooking','crafts']::text[], NULL, 6, 14, 1, 8, 'County run farm day camp at Muscoot Farm in Somers where kids entering grades 1 to 8 help care for the animals, do farm chores, explore the pond, hike, cook and make crafts. Families choose one week; each camper may attend only one week a summer.', NULL, NULL, 425, 425, 425, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '77ae32c7-d402-5879-8da8-81334ea57ddc', 'muscoot-farm-young-farmers-camp-somers', ST_GeogFromText('SRID=4326;POINT(-73.7226 41.3044)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://parks.westchestercountyny.gov/children-camps/muscoot-young-farmers-camp','https://parks.westchestercountyny.gov/find-a-park/muscoot-farm']::text[], '2026-11-26', '2026-11-26', TRUE),
('New Rochelle YMCA Summer Camp', 'New Rochelle YMCA', 'https://nrymca.org/ymca-summer-camp', NULL, 'frontdesk@nrymca.org', '914-632-1818', '50 Weyman Avenue', 'New Rochelle', 'NY', '10805', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['swimming','arts','STEM','sports']::text[], ARRAY['swimming','dance','arts and crafts','games','sports','team building','STEM','cooking','weekly field trips']::text[], NULL, NULL, NULL, NULL, NULL, 'YMCA day camp at the New Rochelle Y with daily swims in the Y''s pool, dance, arts and crafts, STEM and sports, plus a weekly theme and trip or visiting performer. Families sign up by the week across nine weeks from late June to late August.', NULL, NULL, 415, 415, 415, 'week', TRUE, NULL, TRUE, NULL, 'Changes and refunds allowed before May 15, 2026, but the 25% deposit and the $75 registration fee are non-refundable; no refunds or credits after May 15 for any reason.', NULL, NULL, NULL, NULL, 2026, '09c19a79-a1cd-501c-a859-dc7c5b97b59b', 'new-rochelle-ymca-summer-camp-new-rochelle', ST_GeogFromText('SRID=4326;POINT(-73.7826 40.9115)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://nrymca.org/sites/nrymca/files/2026-06/Summer%20Camp%202026%20Parent%20Summer%20Camp%20Handbook.pdf','https://nrymca.org/ymca-summer-camp']::text[], '2026-11-26', '2026-11-26', TRUE),
('Nike Soccer Camp at Pace University', 'US Sports Camps', 'https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-pace-university', NULL, NULL, NULL, 'Pace University, 861 Bedford Road', 'Pleasantville', 'NY', '10570', 'Westchester County, NY', 'specialty', ARRAY['sports']::text[], '{}'::text[], ARRAY['soccer','goalkeeper training','small sided games','scrimmages']::text[], 'coed', 6, 17, NULL, NULL, 'A week long soccer day camp at Pace University''s athletic field house in Pleasantville for ages 6 to 17, led by Pace soccer coaches. Players are grouped by age and ability for technical drills, small sided games and scrimmages, with goalkeeper sessions for beginners and advanced keepers.', 'both', NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '10c12bf1-8bdc-53ab-98bf-f95301e3dd47', 'nike-soccer-camp-pace-university-pleasantville', ST_GeogFromText('SRID=4326;POINT(-73.7841 41.134)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-pace-university']::text[], '2026-11-26', '2026-11-26', TRUE),
('Oasis Day Camp Dobbs Ferry', 'Oasis Day Camp', 'https://oasischildren.com/location/dobbs-ferry-mercy-university/', 'https://oasisdobbsferry.campintouch.com/ui/forms/application/camper/App', 'dobbslc@oasischildren.com', '646-519-5057', 'Mercy University, 555 Broadway', 'Dobbs Ferry', 'NY', '10522', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','STEM','nature']::text[], ARRAY['swim lessons','nature walks','gardening','field sports','court games','team building','martial arts','yoga','drama','arts and crafts','STEM','theme days']::text[], NULL, 3, 15, NULL, NULL, 'A day camp on the Mercy University campus in Dobbs Ferry for ages 3 to 15, with an early childhood program for pre K and kindergarten, a day camp for grades 1 to 6 and teen travel camps for grades 5 to 10. Days mix swim lessons in the campus outdoor pool, sports, gardening, martial arts, drama in a university theater and STEM in a computer lab.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, TRUE, NULL, NULL, NULL, 'Instructional swim and supervised free swim at Mercy University''s private outdoor pool, taught by certified instructors and included in tuition.', NULL, NULL, 2027, '11abe1d1-60df-5f4b-ad96-f0f016a13114', 'oasis-day-camp-dobbs-ferry', ST_GeogFromText('SRID=4326;POINT(-73.8686 41.01)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://oasischildren.com/dates-rates/','https://oasischildren.com/location/dobbs-ferry-mercy-university/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Purchase Day Camp', 'Purchase Community, Inc.', 'https://www.purchasedaycamp.com/', 'https://purchasehouse.org/campsignupguest.php', 'camp@purchasehouse.com', '914-949-2636', '3095 Purchase Street', 'Harrison', 'NY', '10577', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','STEM','leadership']::text[], ARRAY['swimming','sports clinics','karate','ninja course','archery','woodworking','jewelry making','arts and crafts','STEAM','rocketry','paddle sports','mini golf','gaga','cheerleading','cooking','trips','leadership training']::text[], NULL, 3, 15, NULL, NULL, 'A day camp on eight acres around the historic Read Memorial House in Purchase, running since 1947, for ages 3 to 15. Campers have a swim lesson and free swim each day in four heated pools, plus sports, arts, STEAM and karate; middle schoolers add weekly trips and high schoolers train as junior leaders.', 'both', NULL, 840, 1070, 1070, 'week', TRUE, TRUE, NULL, NULL, NULL, 'A Special Education Liaison helps plan for campers with IEPs or 504 plans; families are asked to contact the camp.', 'Four heated pools of different depths; daily American Red Cross Learn to Swim lessons and an afternoon free swim. Preschoolers have their own shallow fountain pool.', NULL, NULL, 2027, '2c89e7ef-5c54-5257-9101-a3d07d7cfc50', 'purchase-day-camp-purchase', ST_GeogFromText('SRID=4326;POINT(-73.7193 41.0235)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://purchasehouse.org/campsignupguest.php','https://www.purchasedaycamp.com/','https://www.purchasedaycamp.com/behindthescenes','https://www.purchasedaycamp.com/fineprint']::text[], '2026-11-26', '2026-11-26', TRUE),
('RCDS Summer Camps', 'Rye Country Day School', 'https://www.ryecountryday.org/academics/summer-programs/rcds-summer-camps', NULL, NULL, '914-925-4605', '3 Cedar Street', 'Rye', 'NY', '10580', 'Westchester County, NY', 'specialty', ARRAY['sports']::text[], '{}'::text[], ARRAY['volleyball','lacrosse','football']::text[], NULL, 8, 14, 3, 8, 'Short sports camps on the Rye Country Day School campus, open to the public and coached by RCDS varsity coaches: girls volleyball for grades 4 to 7, boys lacrosse for grades 3 to 8 and non contact youth football for grades 4 to 8.', 'both', NULL, 300, 350, NULL, 'session', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '04a6673a-0a55-529e-bba2-16d7de25a261', 'rcds-summer-camps-rye', ST_GeogFromText('SRID=4326;POINT(-73.6829 40.9809)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.ryecountryday.org/academics/summer-programs/rcds-boys-lacrosse-camp','https://www.ryecountryday.org/academics/summer-programs/rcds-girls-volleyball-camp','https://www.ryecountryday.org/academics/summer-programs/rcds-summer-camps']::text[], '2026-11-26', '2026-11-26', TRUE)
INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('Read Nature Camp', 'Westchester County Parks', 'https://parks.westchestercountyny.gov/children-camps/nature-camps', 'https://sales.westchestergov.com/', NULL, '(914) 967-8720', 'Playland Parkway', 'Rye', 'NY', '10580', 'Westchester County, NY', 'day', ARRAY['nature']::text[], ARRAY['outdoor']::text[], ARRAY['seashell collecting','fort building','shoreline exploration','nature study']::text[], NULL, 6, 15, 1, 9, 'County run nature day camp at the Edith G. Read Wildlife Sanctuary next to Playland in Rye, for kids entering grades 1 to 9. Campers gather seashells, build forts from bamboo and look for crabs and other shoreline life, in one week sessions.', NULL, NULL, 425, 425, 425, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '64c185ad-6836-5971-8e20-07e2f99ffd98', 'read-nature-camp-rye', ST_GeogFromText('SRID=4326;POINT(-73.6829 40.9809)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://parks.westchestercountyny.gov/children-camps/nature-camps','https://parks.westchestercountyny.gov/read-wildlife-sanctuary']::text[], '2026-11-26', '2026-11-26', TRUE),
('Rye Brook Day Camp', 'Village of Rye Brook Parks & Recreation', 'https://ryebrookny.gov/day-camp', NULL, 'vrbrec@ryebrookny.gov', '914-939-3235', NULL, 'Rye Brook', 'NY', '10573', 'Westchester County, NY', 'day', ARRAY['general']::text[], NULL, ARRAY['field trips','end of season performances']::text[], NULL, 5, 12, 0, 6, 'Village day camp for children entering kindergarten to 6th grade, six weeks from July 6 to August 14, 2026, sold by the week or for the full season, with weekly trips and end of season performances.', NULL, NULL, 545, 2165, 545, 'session', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '88644097-bde6-590f-ba69-46d5edef05c9', 'rye-brook-day-camp-rye-brook', ST_GeogFromText('SRID=4326;POINT(-73.6864 41.03)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://ryebrookny.gov/day-camp','https://ryebrookny.gov/day-camp-fees/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Summer Camp at the Nature Center at Greenburgh', 'Nature Center at Greenburgh', 'https://naturecentergb.org/summer-camp/', NULL, 'chloe@naturecentergb.org', '(914) 723-3470', '99 Dromore Rd.', 'Scarsdale', 'NY', '10583', 'Westchester County, NY', 'day', ARRAY['nature']::text[], ARRAY['STEM','outdoor']::text[], ARRAY['pond study with dip nets','trail exploration','animal care','native species identification','outdoor games']::text[], NULL, 6, 11, 1, 5, 'Weekly nature and science day camp at the Nature Center at Greenburgh for children entering grades 1 to 5. Campers explore the forest trails and pond, study animal behavior, meet the center''s animals such as sulcata tortoises and learn about conservation.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, 'Cancel 30 days or more ahead for a refund minus 20% and processing fees, or full credit; under 30 days, a 50% credit and no refund; under 48 hours, nothing back.', NULL, NULL, NULL, NULL, 2026, '22bb54cc-233c-58b8-af27-1cb210ddb788', 'summer-camp-at-the-nature-center-at-greenburgh-scarsdale', ST_GeogFromText('SRID=4326;POINT(-73.7846 40.9898)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://naturecentergb.org/summer-camp/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Summer Days at the J', 'JCC Mid-Westchester', 'https://jccmw.org/summer-days/', 'https://operations.daxko.com/Online/4072/ProgramsV2/Search.mvc?category_ids=CAT700&', NULL, '(914) 725-7300', '999 Wilmot Rd', 'Scarsdale', 'NY', '10583', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['swimming','performing_arts','STEM','sports']::text[], ARRAY['swimming','gymnastics','dance','musical theater','STEAM','robotics','field trips','gardening','baking','music','sports','arts and crafts']::text[], NULL, 2, 12, NULL, 6, 'Day camp at JCC Mid-Westchester in Scarsdale for toddlers through grade 6. Explorers (twos to kindergarten) play, swim in the indoor pool, garden and bake; Adventurers (grades 1 to 6) pick a morning focus in aquatics, dance and performing arts, trips, gymnastics or STEAM and join general camp activities in the afternoon.', NULL, 'Jewish', 840, 7541, NULL, 'session', TRUE, NULL, FALSE, NULL, 'No refunds unless the JCC cancels the program, except for a documented medical reason or a move of more than 30 miles, prorated on written request with a $35 to $50 processing fee.', NULL, NULL, NULL, NULL, 2027, '7c3f3bb2-23ce-589a-8895-5bf5c77bdfb6', 'summer-days-at-the-j-scarsdale', ST_GeogFromText('SRID=4326;POINT(-73.7846 40.9898)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://jccmw.org/summer-days/']::text[], '2026-11-26', '2026-11-26', TRUE),
('Summer Youth Programs in the Arts', 'SUNY Purchase Youth and Precollege Programs', 'https://www.purchase.edu/academics/youth-and-precollege-programs/summer-youth-programs-in-the-arts/', 'https://www.purchase.edu/academics/youth-and-precollege-programs/register/', NULL, '914-251-6511', '735 Anderson Hill Road', 'Harrison', 'NY', '10577', 'Westchester County, NY', 'specialty', ARRAY['arts','performing_arts']::text[], '{}'::text[], ARRAY['drawing','painting','sculpture','printmaking','filmmaking','singing','creative writing']::text[], NULL, 11, 15, 6, 9, 'Two week arts programs for middle schoolers on the SUNY Purchase campus, taught by professional artists: Young Artists (studio art), Young Writers, Young Filmmakers and a one week Young Vocalists class. Each ends with an exhibition, reading, screening or showcase for families.', 'indoor', NULL, 600, 1200, NULL, 'session', FALSE, NULL, FALSE, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '302ed609-70b6-5704-aca0-9a6c1ff1e993', 'summer-youth-programs-in-the-arts-purchase', ST_GeogFromText('SRID=4326;POINT(-73.7193 41.0235)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.purchase.edu/academics/youth-and-precollege-programs/summer-youth-programs-in-the-arts/','https://www.purchase.edu/academics/youth-and-precollege-programs/youth-young-artists/','https://www.purchase.edu/academics/youth-and-precollege-programs/youth-young-vocalists/']::text[], '2026-11-26', '2026-11-26', TRUE),
('SummerStage', 'Arc Stages', 'https://arcstages.org/summerstage/', 'https://arcstages.org/reg-summer/', NULL, NULL, '147 Wheeler Avenue', 'Pleasantville', 'NY', '10570', 'Westchester County, NY', 'specialty', ARRAY['performing_arts']::text[], '{}'::text[], ARRAY['acting technique','Broadway dance','improv','stage combat','songwriting','costume design','on camera class','rehearsals','performances']::text[], NULL, 5, 18, 0, 12, 'A theatre day camp at Arc Stages in Pleasantville for students entering kindergarten through grade 12. Campers take classes such as acting, Broadway dance, improv and stage combat, then rehearse a show they perform for families at the end of each three or four week session.', 'indoor', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Cancel before April 1 for a 75% refund, before May 1 for 50%, before June 1 for 25%; no refunds after June 1.', NULL, NULL, NULL, NULL, 2026, '7e9d56c9-56cb-5cb6-a239-d01e72497255', 'summerstage-arc-stages-pleasantville', ST_GeogFromText('SRID=4326;POINT(-73.7841 41.134)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://arcstages.org/summerstage/','https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=147+Wheeler+Avenue%2C+Pleasantville%2C+NY&benchmark=Public_AR_Current&format=json']::text[], '2026-11-26', '2026-11-26', TRUE),
('Trailside Nature Camp', 'Westchester County Parks', 'https://parks.westchestercountyny.gov/children-camps/nature-camps', 'https://sales.westchestergov.com/', NULL, '914-864-7322', 'Ward Pound Ridge Reservation, Route 35 and 121 South', 'Lewisboro', 'NY', '10576', 'Westchester County, NY', 'day', ARRAY['nature']::text[], ARRAY['outdoor']::text[], ARRAY['archaeological site visits','crayfish catching','nature games','art','campout']::text[], NULL, 4, 15, NULL, 9, 'County nature camp at the Trailside Nature Museum in Ward Pound Ridge Reservation, Westchester''s largest park, for Pre-K to 9th grade. One week sessions, 9 to 3, explore the reservation with visits to archaeological sites, crayfish catching, nature games and art; Pre-K mornings only, and two week sessions for grades 7 to 9 with an optional campout.', 'outdoor', NULL, 200, 425, 425, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '4f3d0745-e090-560a-a442-550a300a77ce', 'trailside-nature-camp-cross-river', ST_GeogFromText('SRID=4326;POINT(-73.5883 41.2661)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://parks.westchestercountyny.gov/children-camps/nature-camps','https://parks.westchestercountyny.gov/ward-pound-ridge-reservation']::text[], '2026-11-26', '2026-11-26', TRUE),
('Westchester Summer Day', 'Westchester Day School', 'https://www.westchesterday.org/westchester-summer-day/dates-rates', 'https://www.westchesterday.org/westchester-summer-day/dates-rates/enroll', 'wsd@westchesterday.org', '914-698-8900', '856 Orienta Ave', 'Mamaroneck', 'NY', '10543', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','faith']::text[], ARRAY['aquatics','beach','ropes course','jewish enrichment','israeli culture','creative arts','culinary arts','music','baseball','basketball','hockey','soccer','tennis','volleyball']::text[], NULL, 3, 14, NULL, 8, 'Day camp of Westchester Day School on Long Island Sound in Mamaroneck for children from age 3 to 8th grade, rooted in Jewish values, with swim, beach, a ropes course, sports, arts, cooking and music. Campers in 5th to 8th grade pick an active or creative track each week and take day and overnight trips. Kosher lunch and snacks are included; busing costs extra.', 'both', 'Jewish', 6250, 7100, NULL, 'session', TRUE, TRUE, TRUE, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '16c36a8d-3d81-54a4-886a-e670cf58127e', 'westchester-summer-day-mamaroneck', ST_GeogFromText('SRID=4326;POINT(-73.734 40.9487)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://cdn.usa.digistormhosting.com/wds-us-ny-1200-website-2023/content/Westchester-Summer-Day-2027-Rates.pdf?v=1790354205','https://www.westchesterday.org/westchester-summer-day/dates-rates','https://www.westchesterday.org/westchester-summer-day/dates-rates/enroll','https://www.westchesterday.org/westchester-summer-day/dates-rates/wsd-financial-assistance','https://www.westchesterday.org/westchester-summer-day/wsd-mission-values','https://www.westchesterday.org/westchester-summer-day/wsd-mission-values/activities','https://www.westchesterday.org/westchester-summer-day/wsd-mission-values/programs-by-division','https://www.westchesterday.org/westchester-summer-day/wsd-mission-values/summer-transport','https://www.westchesterday.org/westchester-summer-day/wsd-mission-values/wsd-before-and-aftercare']::text[], '2026-11-26', '2026-11-26', TRUE),
('Westchester County Summer Programs (YMCA of Central and Northern Westchester)', 'YMCA of Central and Northern Westchester', 'https://ymca-cnw.org/summer-programs-2/', 'https://ymca-cnw.ce.eleyo.com/child-care/5/summer-programs?preview=true', 'info@ymca-cnw.org', '(914) 949-8030', '148 Hamilton Ave', 'White Plains', 'NY', '10601', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['sports','STEM']::text[], ARRAY['water play','structured sports','science lessons','field trips','themed dress up days','special projects']::text[], NULL, 6, 11, 1, 5, 'Six week YMCA summer day program for children entering grades 1 to 5 (Big Kid Summer), held at the White Plains YMCA and in Valhalla, with weekly themes, sports, science lessons, special visitors and field trips. A Pee Wee program for the Y''s own UPK students also runs at these sites and at French Hill School in Yorktown Heights.', NULL, NULL, 440, 480, 440, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '41c1965e-3787-58ec-bf29-26b47f15a4d1', 'ymca-of-central-and-northern-westchester-summer-program-white-plains', ST_GeogFromText('SRID=4326;POINT(-73.7629 41.034)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=148+Hamilton+Ave%2C+White+Plains%2C+NY&benchmark=Public_AR_Current&format=json','https://ymca-cnw.org/summer-programs-2/']::text[], '2026-11-26', '2026-11-26', TRUE),
('YMCA of Yonkers Summer Camp', 'YMCA of Yonkers', 'https://yonkers.recliquecore.com/school-aged-child-care-sacc/summer-camp/', NULL, NULL, '(914) 963-0183', '17 Riverdale Ave', 'Yonkers', 'NY', '10701', 'Westchester County, NY', 'day', ARRAY['general']::text[], ARRAY['sports','arts','STEM']::text[], ARRAY['STEAM','open play','summer learning','organized sports','arts and crafts','dance','drumming','team building','field trips','barbecues']::text[], NULL, 5, 14, 0, 7, 'Full day YMCA summer camp at the Yonkers Y on Riverdale Avenue for kids ages 5 to 14 (kindergarten to grade 7), with sports, STEAM, arts, dance and drumming, summer learning and field trips. Families sign up by the week.', NULL, NULL, 325, 325, 325, 'week', NULL, NULL, TRUE, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '1548dc79-df3e-5d88-b438-55da04841082', 'ymca-of-yonkers-summer-camp-yonkers', ST_GeogFromText('SRID=4326;POINT(-73.8988 40.9312)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://yonkers.recliquecore.com/school-aged-child-care-sacc/summer-camp/']::text[], '2026-11-26', '2026-11-26', TRUE)
